INSERT INTO career_facts (
  id, query_type, course_name, quick_answer, key_caveat, point_to
) VALUES
  ('course-countries-nursing', 'Course ? Countries', 'Nursing', 'Top: UK (4-8 months, NHS), Saudi Arabia (3-6 months, tax-free), Canada (12-24 months, PR pathway). USA is highest-paying but EB-3 backlog is 5-7 years. Germany via Triple Win (free language training).', 'NCLEX pass rate for PH nurses ~35-42% under NextGen format. Start CBT immediately after NLE. Gulf is stepping stone while waiting for USA EB-3.', 'DESTINATIONS'),
  ('course-countries-physical-therapy', 'Course ? Countries', 'Physical Therapy', 'Top: USA (FCCPT + NPTE, EB-2 current for PH as of April 2026), Saudi Arabia (3-6 months tax-free), Australia (AHPRA, MLTSSL), Canada (PCE exam, Express Entry).', 'FCCPT evaluation takes ~26 months — start the day you get your PRC license. EB-2 is currently better than nursing EB-3 for PH PTs.', 'DESTINATIONS'),
  ('course-countries-occupational-therapy', 'Course ? Countries', 'Occupational Therapy', 'Top: USA (NBCOT, EB-2 current), UK (HCPC, shortage occupation), Australia (NDIS creating massive demand), Saudi Arabia (3-6 months tax-free).', 'Must be from WFOT-accredited school — verify at wfot.org BEFORE enrolling. Non-WFOT programs block all international licensure.', 'DESTINATIONS'),
  ('course-countries-medical-technology', 'Course ? Countries', 'Medical Technology', 'Top: USA (ASCPi exam, Pearson VUE Manila), Saudi/UAE (DataFlow + SCFHS/DHA, 3-6 months), Australia (AUD 111k avg), Canada (CSMLS exam, Express Entry).', 'ASCPi requires 1 year post-graduation lab experience in at least 4 sections. Start accumulating this immediately after MTLE.', 'DESTINATIONS'),
  ('course-countries-medicine', 'Course ? Countries', 'Medicine', 'Specialists: Saudi Arabia immediate (no re-residency, USD 120k-264k tax-free). UK: PLAB 1+2 via GMC (PLAB 1 in Manila, 12-18 months). USA: USMLE + ECFMG + residency match (5-10 years).', 'USA residency: best IMG match in Internal Medicine, Family Medicine, Psychiatry, Pathology. J-1 visa has 2-year home return requirement (waivable).', 'DESTINATIONS'),
  ('course-countries-civil-engineering', 'Course ? Countries', 'Civil Engineering', 'Top: UAE (6 months, NEOM/giga-projects), Saudi Arabia (6 months), Australia (Engineers Australia CDR, MLTSSL), NZ Green List (2-year PR pathway), Canada (Express Entry).', 'Washington Accord 2023: PH graduates from ABET-accredited programs have mutual recognition in 21 countries. CDR takes 3-6 months to prepare.', 'DESTINATIONS'),
  ('course-countries-electronics-engineering', 'Course ? Countries', 'Electronics Engineering', 'Top: Taiwan (TSMC/MediaTek, Taiwan Gold Card), South Korea (Samsung/SK Hynix KRW 102M avg), Germany (EU Blue Card, ASML/Infineon), Japan (Sony/Renesas), USA ($80k-$130k H-1B).', 'Semiconductor specialization pays 2x vs general ECE. EB-2/H-1B for USA; Blue Card for Germany (fastest EU PR at 21 months). Taiwan mid-career $80k-$115k.', 'DESTINATIONS'),
  ('course-countries-accountancy-cpa', 'Course ? Countries', 'Accountancy / CPA', 'Top: UAE (tax-free, DIFC, 1-2 years), Singapore (ASEAN RFPA MRA active Jan 2025), Australia (CPA Australia MRA with PICPA), USA (US CPA now in Philippines since July 2024).', 'Big 4 intracompany L-1 transfer is most reliable USA pathway. UK and Canada require ACCA/CPA Canada respectively — no direct MRA. Canada is slowest (4-6 years).', 'DESTINATIONS'),
  ('course-countries-secondary-education', 'Course ? Countries', 'Secondary Education', 'Top: UK (QTS FREE from Aug 2025, Skilled Worker Visa), UAE (5 months, tax-free + housing), Australia (AITSL assessment, AUD 79k-92k), NZ Green List Tier 2 (secondary teachers).', 'STEM subjects (Maths, Physics, Computing) have highest global demand and UK bursaries (GBP 22k-29k). Korea E-2 visa EXCLUDES Filipino citizens — important warning.', 'DESTINATIONS'),
  ('course-countries-geodetic-engineering', 'Course ? Countries', 'Geodetic Engineering', 'Top: Australia (AUD 142k avg, 2,000-person deficit until 2029, MLTSSL), UAE (construction, 8 months), Saudi Arabia (NEOM surveying), NZ Green List Tier 2, Canada (Express Entry).', 'Australia is the clear #1 — highest salary and documented shortage. FIFO mining survey can earn AUD 150k-200k. CDR or SSSI assessment required.', 'DESTINATIONS'),
  ('course-countries-merchant-marine', 'Course ? Countries', 'Merchant Marine', 'Global via MARINA-licensed manning agencies. Top vessel types: LNG/gas carriers (+30-40% salary premium), North Sea offshore/OSVs (USD 10k-18k/month), Japanese shipping (NYK/MOL for LNG).', 'ITF AB minimum $1,808/month (2025). Master minimum $7,045/month. All OFW seafarer earnings are PH income tax-exempt. DP certification opens offshore/wind sector.', 'DESTINATIONS'),
  ('course-countries-nursing-specific-germany', 'Course ? Countries', 'Nursing (specific: Germany)', 'Triple Win Project: Free German language training (B1 in PH, B2 in Germany). Salary EUR 2,907-3,629 as nursing assistant rising to EUR 3,200-4,500 as licensed nurse. PR after 5 years (3 with integration).', 'Language is mandatory and takes 18-24 months total. GIZ covers relocation costs. Philippines is founding Triple Win partner since 2013.', 'PROGRAMS'),
  ('country-courses-uk', 'Country ? Courses', 'UK', 'Highest demand: Nursing (NHS CBT in Manila, 4-8 months), PT/OT (HCPC shortage occupation), Social Work (HCPC shortage), Teachers (QTS free Aug 2025), Medicine (PLAB 1 in Manila).', 'Health and Care Worker Visa has reduced fee (GBP 232) and no NHS surcharge. ILR after 5 years ? citizenship. IELTS 7.0 or OET Grade B required for healthcare.', 'DESTINATIONS'),
  ('country-courses-usa', 'Country ? Courses', 'USA', 'Highest demand: Nursing (EB-3, high backlog), PT (EB-2 current, FCCPT+NPTE), OT (EB-2 current, NBCOT), MedTech (ASCPi), CS/IT (H-1B lottery), Engineers (H-1B/EB-2).', 'H-1B lottery is main barrier for engineers/IT. EB-3 backlog 5-7yrs for nurses. EB-2 currently current for PH PTs and OTs (April 2026). PTs/OTs are strategically better positioned than nurses right now.', 'SUMMARY'),
  ('country-courses-saudi-arabia', 'Country ? Courses', 'Saudi Arabia', 'Highest demand: All healthcare (nurses, doctors, MedTech, PT, OT, pharmacists — all via DataFlow + SCFHS). Engineers (CE, ME, ChE, EE — via Saudi Council of Engineers). No licensing exam for most; just DataFlow.', 'All income tax-free. Housing + annual flight + benefits included in most packages. No PR pathway — plan for 2-5 years then move to Western country. Fastest deployment globally (3-6 months most courses).', 'DESTINATIONS'),
  ('country-courses-canada', 'Country ? Courses', 'Canada', 'Highest demand: Nursing (NOC 31301, NCLEX-RN), Healthcare workers (Express Entry FSW), Civil Engineers (NOC 22301), MedTech (NOC 32120, CSMLS), Social Work (NOC 42201), CPA (long process).', 'Express Entry can process in 6 months after ITA. Provincial Nominee Programs add points. Most healthcare workers get PR within 12-24 months of decision to migrate.', 'DESTINATIONS'),
  ('country-courses-australia', 'Country ? Courses', 'Australia', 'Highest demand: Geodetic Engineering (2,000-person deficit), OT (NDIS), Nursing (AHPRA), PT (MLTSSL), Teachers (AITSL), MedTech (AUD 111k avg), Geology (VETASSESS, critical minerals), Vet Med (shortage).', 'CDR/VETASSESS/AHPRA/AITSL are the credential assessment bodies depending on profession. MLTSSL is the key list — if your occupation is on it, you qualify for PR visa subclasses 189/190.', 'DESTINATIONS'),
  ('country-courses-germany', 'Country ? Courses', 'Germany', 'Highest demand: Nursing (Triple Win, free language training), ME/ChE/EE/ECE (EU Blue Card, EUR 43,759 threshold 2025), IT/CS (Blue Card), Software Engineering (Blue Card).', 'German B1 required for most roles (free via Triple Win for nurses). EU Blue Card gives PR in 21-33 months. B2 needed for career progression. English-only roles exist in large tech companies.', 'PROGRAMS'),
  ('fastest-pathway-any-course', 'Fastest pathway', 'Any course', 'Saudi Arabia, UAE, Qatar for most healthcare and engineering courses: 3-6 months from PRC license to deployment. DataFlow verification is the main requirement (4-8 weeks).', 'Gulf has no PR pathway and currency risk. Use as stepping stone to save money while processing Western country applications.', 'DESTINATIONS'),
  ('best-pr-pathway-healthcare', 'Best PR pathway', 'Healthcare', 'UK: ILR after 5 years (Health & Care Worker Visa). Canada: Express Entry 12-24 months (fastest). Australia: Skilled migration 12-18 months. NZ: Green List (some direct PR).', 'UK ILR requires continuous residence. Canada Express Entry requires CLB 9 English (IELTS 7.0). Australia requires IELTS 7.0+ for most healthcare professions.', 'COUNTRY_PROFILES'),
  ('best-pr-pathway-engineering', 'Best PR pathway', 'Engineering', 'New Zealand Green List Tier 2: Civil Engineers, Geodetic Engineers ? work-to-residence in 2 years. Canada Express Entry: 12-24 months. Australia skilled migration: 12-18 months (MLTSSL = direct 189 visa).', 'Washington Accord 2023: ABET-accredited PH engineering programs have mutual recognition in 21 countries. CDR for Engineers Australia takes 3-6 months. EU Blue Card: PR as fast as 21 months in Germany.', 'COUNTRY_PROFILES'),
  ('critical-warning-nursing-usa', 'Critical warning', 'Nursing + USA', 'EB-3 visa retrogression for Philippines: 5-7 year wait from I-140 petition approval to actual visa issuance as of June 2026. Not a 2-year plan — this is a long-game commitment.', 'Strategy: Get PH license ? NCLEX prep ? Pass NCLEX ? Gulf deployment (save money, build experience) ? employer files I-140 ? wait for priority date ? immigrate to USA. Total: 7-10 years.', 'SUMMARY'),
  ('critical-warning-nursing-nclex', 'Critical warning', 'Nursing + NCLEX', 'Philippine pass rate under NextGen NCLEX (2023+): ~35-42%. Significantly below US national average of ~85%. NextGen tests clinical reasoning, not memorization. Budget for 1-2 retakes.', 'Best prep: Uworld, Archer Review, NCLEX Mastery. Focus on clinical decision-making and Next Generation question types. Practice with case studies not just multiple choice.', 'SUMMARY'),
  ('critical-warning-korea-e-2-visa', 'Critical warning', 'Korea E-2 visa', 'Korea E-2 visa (native language teacher) explicitly EXCLUDES Filipino citizens from eligibility by policy. This is a recurring misconception. Filipino teachers CANNOT use E-2 to teach in Korea.', 'Korean government''s E-2 policy lists eligible countries by passport — Philippines is not included. Filipino teachers can work in Korea via other visa categories (E-7 for specialized education) but not E-2.', 'DESTINATIONS'),
  ('critical-warning-agriculture-fisheries', 'Critical warning', 'Agriculture/Fisheries', 'Japanese SSW-i Agriculture and Israeli bilateral programs are for semi-skilled workers. A BS Agriculture or BS Fisheries graduate earns the SAME as a high school graduate in these programs.', 'Better international route: Add HACCP + ISO 22000 certifications. These open UAE/Saudi food safety QA roles ($1,360-$4,100/month) that actually use your degree-level knowledge.', 'SUMMARY'),
  ('critical-warning-criminology', 'Critical warning', 'Criminology', 'Philippine RCrim license does not qualify for police officer positions in any foreign country. All countries require citizenship for police/law enforcement. RCrim is NOT equivalent to foreign law enforcement credentials.', 'Target: Security management (ASIS CPP/PSP certification — internationally portable), forensic science (additional lab credentials), corrections (Canada/Australia — foreign nationals eligible), digital forensics (global, remote-friendly).', 'SUMMARY'),
  ('policy-change-2025-uk-qts-teachers', 'Policy change 2025', 'UK QTS (Teachers)', 'UK QTS is FREE for eligible overseas teachers from August 2025. Previously cost GBP 255. iQTS route allows teacher training IN Philippines — recognized in UK. Shortage subject bursaries: GBP 22k-29k for Maths, Physics, Computing.', 'Applies to: teachers with overseas qualification + 2 years experience (from Aug 2025, only 1 year + QTS training sufficient via iQTS). UK is running largest international teacher recruitment campaign in NHS history.', 'PROGRAMS'),
  ('policy-change-2025-asean-cpa-rfpa-mra', 'Policy change 2025', 'ASEAN CPA/RFPA MRA', 'ASEAN MRA for Accountancy activated January 31, 2025. Philippine CPAs can now register as Registered Foreign Professional Accountants (RFPA) in Singapore (ISCA), Thailand (FAP), Malaysia, Indonesia, and other ASEAN signatories.', 'RFPA allows practice under supervision of local CPA — not fully independent practice in all countries. Singapore RFPA requires ISCA registration. This replaces older, less-functional MRA arrangements.', 'PROGRAMS'),
  ('policy-change-2024-us-cpa-exam-in-philippines', 'Policy change 2024', 'US CPA Exam in Philippines', 'As of July 1, 2024, candidates can sit US CPA exams (all 4 parts) in the Philippines through NASBA testing centers. Previously required travel to USA, Guam, Japan, or Bahrain. States with no SSN requirement: Wisconsin, New York, Montana, Illinois, South Dakota.', 'Game-changer for Philippine CPAs targeting USA. Eliminates need to fly abroad for exam. The 4 parts are: Financial Accounting & Reporting (FAR), Auditing & Attestation (AUD), Taxation & Regulation (REG), Business Analysis & Reporting (BAR) or ISC or TCP.', 'PROGRAMS'),
  ('policy-change-2023-philippines-washington-accord', 'Policy change 2023', 'Philippines Washington Accord', 'Philippines became full Washington Accord signatory via PTC-ACBET in 2023. Graduates from ABET-accredited Philippine engineering programs now have mutual recognition in 21 member countries including USA, Australia, Canada, UK, Japan, South Korea, Singapore.', 'Not all PH engineering schools are ABET-accredited. Students should verify their school''s accreditation status. Unaccredited programs still require CDR or other individual assessment for each destination country.', 'SUMMARY'),
  ('note-ARCH-001', 'Notes', 'BS Architecture', 'Gulf (UAE/Saudi) is the largest and fastest immediate employer of Filipino architects — no licensing exam required, only employer sponsorship and SoE registration. Australia has strong demand and a structured pathway (AACA + APE), with architects on the skilled occupation shortage list. USA pathway requires completing NCARB''s Architectural Experience Program (AXP, min 3,740 hours) and passing 6-division ARE — Filipino architects commonly work as ''architectural staff'' while accumulating hours. UK requires ARB Part 3 equivalent; no MRA currently exists between Philippines and UK, so international assessment route applies. Canada requires CACB academic assessment plus Internship in Architecture Program (IAP). NEOM mega-project in Saudi Arabia is actively hiring architects at premium packages (SAR 200k-400k/yr).', 'Pass ALE before graduating or within 1 year — it is your biggest salary differentiator abroad. Target UAE/Dubai for fastest entry and best first-3-years income. Build BIM (Revit/ArchiCAD) skills — Gulf firms specifically require this. After 3-5 years Gulf experience, USA or Australia become realistic with your accumulated portfolio.', 'SUMMARY'),
  ('note-ARCH-002', 'Notes', 'BS Environmental Planning', 'BS Environmental Planning is primarily a domestic profession in the Philippines (tied to HLURB/DHSUD, LGU comprehensive land use plans). International pathways exist but require repackaging skills: urban planning, land use, EIA, GIS, climate resilience. Top international pathway is through multilateral development organizations (World Bank, ADB, UN-Habitat, UNDP) — highly competitive but prestigious. Australia and Canada have active urban planning markets. PIEP has Saudi and Qatar chapters — indicating Gulf demand. EnP graduates can also enter the Gulf as ''urban planning consultants'' on project-based contracts.', 'Master GIS (ArcGIS, QGIS) and climate-resilience planning tools — these are the most in-demand skills in international development orgs. A master''s degree in Urban Planning (UP Diliman, or abroad) dramatically improves World Bank/ADB competitiveness. AICP certification unlocks USA urban planning jobs.', 'SUMMARY'),
  ('note-ARCH-003', 'Notes', 'BS Fine Arts (BFA)', 'BS Fine Arts has no standard OFW pathway like nursing or engineering. However, strong international income streams exist through: (1) FREELANCE — digital illustration, concept art, graphic design on Upwork/Fiverr with global clients paying USD rates (2) ANIMATION STUDIOS — Canada (Ottawa/Vancouver), USA (California), Singapore, Japan hire Filipino animators and concept artists for film, TV, and gaming (3) GAME/CONCEPT ART — US gaming studios pay USD 60k-123k+ for concept artists; remote-first game studios increasingly common. NFT/digital art market has stabilized post-2022 peak but remains a revenue stream. Most impactful specializations: 2D/3D animation, concept art, character design, visual effects, UI/UX illustration.', 'Your portfolio is your passport. Build a professional digital portfolio (ArtStation, Behance) while still in school. Master one digital tool deeply (Procreate, Photoshop, Clip Studio Paint, Blender). Freelance on Fiverr/Upwork from Year 2 — international clients pay 5-10x PH rates. Target Canadian animation studios or Singapore studios for first full-time abroad role.', 'SUMMARY'),
  ('note-ARCH-004', 'Notes', 'BS Interior Design', 'Interior design has strong Gulf demand driven by Saudi Vision 2030 fit-out projects, UAE luxury hospitality, and Qatar post-World Cup commercial development. IDLE-licensed Filipino interior designers are recognized as qualified professionals. In 2025, PRC established the IPID (Indonesia-Philippines Interior Designer) bilateral recognition agreement — first formal international MRA for interior designers. Australia (VETASSESS pathway) and Singapore (Employment Pass) are strong longer-term destinations. Mid-to-senior level designers command significant premiums. BIM/3D rendering skills (3ds Max, SketchUp, Revit) are key differentiators.', 'Pass IDLE before going abroad — it is your proof of competency. Build a strong visual portfolio with renders and completed project photos. Master 3ds Max + AutoCAD + SketchUp. UAE/Saudi is the fastest entry — look for ''fit-out designer'' and ''FF&E designer'' roles at large project firms.', 'SUMMARY'),
  ('note-ARCH-005', 'Notes', 'BS Landscape Architecture', 'Landscape architecture is a niche OFW pathway but offers real opportunities. Australia has ongoing shortages (AILA VETASSESS-endorsed pathway, visa subclasses 189/190/491 available). Gulf demand driven by NEOM''s ''zero-waste green city'' mandate, UAE parks/resort landscaping, and Saudi Vision 2030 greening projects. UK (BALI) and Canada (CSLA) are viable but slower. NEOM''s The Line, Sindalah island, and Leyja resort projects actively require landscape architects. Sustainable design and water-sensitive landscape design are the most in-demand specializations globally. New Zealand is NOT on the long-term skill shortage list for landscape architects (as of 2025 search data).', 'Get LALE licensure and then target Australia (AILA VETASSESS path) or UAE/Saudi (fastest entry). Specialize in sustainable/drought-tolerant design — this is critical for both Gulf arid climate and Australian water-sensitive design. Master AutoCAD + Lumion + GIS for strong applications.', 'SUMMARY'),
  ('note-BUS-002', 'Notes', 'BS Business Analytics', 'One of the hottest global fields. Filipino graduates with SQL, Python, Tableau, Power BI, and machine learning skills are globally competitive. Singapore entry-level data analysts earn SGD 48,000-58,000/yr (~USD 35,000-43,000). Australia average AU$72,808/yr (~USD 47,000). USA entry-level USD 56,000-75,000. Remote roles for US/EU companies pay USD 80,000-120,000+. Australia PR pathway via CSOL list is strong — 30%+ job growth projected 2026-2030. Singapore Employment Pass requires minimum SGD 5,000/month (2025 threshold). Canada median supply chain/analytics consultant ~CAD 81,000.', 'Master the toolkit: SQL, Python, Tableau or Power BI, and one cloud platform (AWS or Azure). Singapore is the fastest path — Employment Pass leads to PR in 2-3 years. Australia offers the clearest permanent residency pathway via skilled migration. Remote work for US companies is viable from Day 1 with 2-3 years of experience.', 'SUMMARY'),
  ('note-BUS-003', 'Notes', 'BS Hospitality Management', 'Filipinos make up a large share of hospitality staff in UAE, Saudi Arabia, Singapore, and cruise lines globally. UAE: Front Office Agent AED 6,000-9,000/month (~USD 1,600-2,450), Restaurant Supervisor AED 7,000-10,000/month (~USD 1,900-2,700), F&B Manager AED 15,000-25,000/month (~USD 4,000-6,800). Tax-free income + free housing + free flights = high savings rate. Singapore: average USD 50,000/yr for mid-level roles, S Pass threshold SGD 3,150/month (Sep 2025). Saudi Arabia adding 25+ new luxury hotels 2025-2027 under Vision 2030. Cruise lines: USD 15,000-36,000/yr (Carnival/RCCL median ~USD 15,000 but includes free room/board/meals).', 'UAE and Gulf are the fastest track — agencies like POEA-accredited recruiters place fresh graduates in 3-4 months. Get a hotel brand certification (Marriott or Hilton online training) before applying. Cruise lines offer excellent savings since accommodation and food are provided. Target supervisor-level by Year 2 abroad.', 'SUMMARY'),
  ('note-BUS-004', 'Notes', 'BS Tourism Management', 'Tourism Management overlaps heavily with Hospitality Management for entry-level abroad roles. Key differentiators: destination marketing, tour operations, tourism policy, sustainable/ecotourism management. UN Tourism is headquartered in Madrid — salaries exempt from Spanish income tax. International tourism management salaries in USA average USD 103,000-133,500 (mid-to-senior level). Destination marketing managers earn USD 60,000-85,000. Tour guides in Italy/France/Japan earn EUR 20,000-33,000. ASEAN tourism sector is growing — Philippines and Indonesia are key markets. Heritage tourism and ecotourism roles growing globally. Cruise lines also recruit tourism graduates for shore excursions/travel desk roles.', 'Tourism Management gives you more career versatility than pure hospitality — you can go into policy, DMO work, airline operations, or international NGOs. The fastest cash path is still Gulf hotel/resort work. For the premium career track: IATA certification + 2 years experience = airline or airport management roles internationally. For ecotourism and development work: target ASEAN and international NGOs.', 'SUMMARY'),
  ('note-OTH-004', 'Notes', 'AB/BS Economics', 'Economics is the most academically demanding of the 6 courses in this cluster for international premium roles. ADB YPP salary starts ~USD 70,000-90,000 + tax-exempt in Philippines context. World Bank entry roles ~USD 95,000-170,000 mid-level. IMF economist entry (PhD hire) >USD 120,000. However, undergraduate economics graduates without Masters can still find strong roles: financial analyst tracks in Singapore/Australia, policy analyst roles in government ministries, development sector NGOs. Median starting salary for economics majors in USA ~USD 74,000. Singapore financial analyst entry SGD 45,000-60,000/yr. Development NGO entry USD 35,000-55,000.', 'For the premium multilateral track (ADB/World Bank/IMF): pursue a Masters or PhD in Economics, preferably from a top US or UK university. ADB YPP is actually ideal for Filipinos — headquarters is in Manila so you get international salary while living in the Philippines. For finance track: take CFA Level 1 concurrently with or after graduation. For development track: UNDP and NGO junior analyst roles are accessible with just a bachelor''s degree and 1-2 years of relevant experience.', 'SUMMARY'),
  ('note-OTH-005', 'Notes', 'BS Finance', 'BS Finance is among the highest-ceiling non-board courses for international careers. CFA charterholder average Singapore salary USD 107,493 (entry USD 76,073). Dubai entry-level finance AED 120,000-180,000/yr (~USD 32,000-49,000) tax-free. Dubai investment banking analyst AED 240,000-420,000/yr (~USD 65,000-114,000) at bulge bracket banks. London mid-level CFA GBP 80,000-100,000+/yr. Singapore financial analyst entry SGD 60,000-90,000/yr. HK entry HKD 30,000-50,000/month. CFA Level 1 alone is a strong signal for entry-level roles — do not wait for full charterholder status. DIFC has 3,000+ registered companies; Islamic finance is a growing specialty.', 'Start CFA Level 1 in your 3rd or 4th year of college — you can take it without a degree. Pass CFA Level 1 before graduation; this immediately makes you competitive for analyst roles in Singapore and Dubai. Dubai DIFC is the fastest high-paying destination (tax-free). Singapore requires Employment Pass threshold (SGD 5,000+/month) so CFA Level 1 helps justify higher starting offer. For Islamic finance specialty: add IFQ certification alongside CFA.', 'SUMMARY'),
  ('note-OTH-006', 'Notes', 'BS Business Administration (BSBA)', 'BSBA is the broadest business degree — international success depends almost entirely on specialization chosen. Top international pathways by specialization: (1) Operations/Supply Chain: Canada and Australia have strong demand — supply chain manager median CAD 137,000 in Canada, AUD 145,000 in Australia. (2) HR Management: Multinational HR roles in Singapore, UAE; HR BPO sector growing. (3) Marketing: Digital marketing roles globally; SEO/paid media open to remote work. (4) Entrepreneurship/General Management: OFW pathway via retail/restaurant management in Gulf, US, Canada. Note: Many BSBA graduates take OFW routes as service crew, store managers, restaurant supervisors — these are legitimate, well-paying paths especially in Gulf states. Gulf entry-level service/management roles: USD 18,000-35,000 tax-free. Canada/Australia skilled migration for management roles: USD 50,000-75,000+ starting.', 'BSBA is versatile but you must pick a lane. Supply Chain is the highest-paying international track — Canada and Australia actively recruit. Marketing is increasingly remote-work friendly. HR in multinationals is a solid Singapore/UAE path. If not specialized: the Gulf OFW pathway (UAE, Qatar, Saudi) is fast and reliable for restaurant/retail management. Get one professional certification in your specialization: PMP, CSCP, or SHRM-CP.', 'SUMMARY'),
  ('note-ENG-001', 'Notes', 'BS Agricultural and Biosystems Engineering', 'Philippines Washington Accord membership (2023) strengthens credential recognition for ABET-accredited programs. Strong fit for Canada''s agri-food tech sector and Australia''s precision agriculture industry.', 'Target Canadian agri-food companies under NOC 21399 and pursue a PEng pathway via Engineers Canada after 4 years of Canadian work experience.', 'SUMMARY'),
  ('note-ENG-002', 'Notes', 'BS Aircraft Maintenance Technology', 'CAAP license is recognized by Gulf airlines; Emirates and Etihad actively recruit Filipino AMTs. EASA Part 66 B1/B2 conversion opens European and global pathways.', 'Get CAAP license first, then immediately pursue EASA Part 66 B1 or B2 type rating conversion to unlock European airline opportunities.', 'SUMMARY'),
  ('note-ENG-003', 'Notes', 'BS Aviation Related Programs', 'Covers broad aviation specializations beyond AMT; Gulf aviation expansion (UAE, Qatar, Saudi) sustains strong demand for Filipino aviation professionals across MRO, safety, and operations roles.', 'Identify your specific track early (safety officer, dispatcher, avionics, airport ops) and pursue the corresponding CAAP/ICAO certification before graduating.', 'SUMMARY'),
  ('note-ENG-004', 'Notes', 'BS Ceramic Engineering', 'Advanced ceramics are critical for semiconductor packaging, EV battery separators, aerospace thermal protection, and biomedical implants — niche but growing demand. Philippines Washington Accord 2023 membership supports credential recognition.', 'Focus coursework on advanced/technical ceramics (semiconductors, biomaterials) rather than traditional ceramics to access higher-paying global markets.', 'SUMMARY'),
  ('note-ENG-007', 'Notes', 'BS Computer Engineering', 'BLS median for Computer Hardware Engineers was $155,020 (May 2024). Taiwan semiconductor demand (TSMC, MediaTek) is exceptional; Philippines Washington Accord 2023 membership aids international recognition.', 'Build an FPGA or ASIC project portfolio on GitHub and target TSMC/MediaTek Taiwan Gold Card program which has a fast 30-day processing track for qualified engineers.', 'SUMMARY'),
  ('note-ENG-008', 'Notes', 'BS Electrical Engineering', 'BLS median EE salary $125,100 (May 2025). UAE construction and power sector pays AED 10,000—18,000/mo tax-free. Australia MLTSSL listed. Canada NOC 22310. Philippines Washington Accord 2023 aids recognition.', 'Get your PRC EE license, then pursue UAE DEWA/ADNOC pre-qualification or Australian Engineers Australia skills assessment simultaneously to open two high-paying markets at once.', 'SUMMARY'),
  ('note-ENG-010', 'Notes', 'BS Engineering Technology', 'Primarily a domestic qualification; limited international recognition compared to BS Engineering degrees. Best pathway is to use the degree as a stepping stone to licensed engineering programs or TESDA-aligned technical supervision roles.', 'Consider pursuing a BS in a licensed engineering discipline afterward, or build a career in technical training and TESDA assessment centers where this degree is well-recognized.', 'SUMMARY'),
  ('note-ENG-011', 'Notes', 'BS Food Engineering', 'Global food security concerns and food tech innovation drive sustained demand. Netherlands (Wageningen, Unilever, FrieslandCampina) and Singapore (food security hub) are strategic targets. Philippines Washington Accord 2023 aids recognition.', 'Get an ISO 22000 Food Safety Management Systems lead auditor certificate before graduating — it''s a globally recognized credential that food multinationals specifically require.', 'SUMMARY'),
  ('note-ENG-013', 'Notes', 'BS Industrial Engineering', 'BLS median IE salary $101,140 (May 2024); projected 11% job growth 2024-2034 (much faster than average). Versatile degree applicable across manufacturing, logistics, healthcare, and tech. Philippines Washington Accord 2023 aids recognition.', 'Earn your Lean Six Sigma Green Belt or Black Belt certification before graduating — it''s the single most transferable credential for industrial engineers across all international markets.', 'SUMMARY'),
  ('note-ENG-014', 'Notes', 'BS Industrial Technology', 'Primarily a domestic qualification designed for technical education and TESDA-aligned industries. Limited international recognition as an engineering credential; treated as technician level abroad.', 'Supplement with Lean Six Sigma Yellow Belt and TESDA assessor accreditation to maximize domestic earning potential and teaching opportunities at TESDA-accredited centers.', 'SUMMARY'),
  ('note-ENG-015', 'Notes', 'BS Manufacturing Engineering', 'Reshoring trends in USA and EU combined with Industry 4.0 automation investments drive strong demand. Philippines Washington Accord 2023 membership aids recognition in Washington Accord signatory countries.', 'Get certified in CAD/CAM software (Siemens NX or CATIA) and complete a Lean Six Sigma Green Belt — these two credentials open doors at tier-1 automotive and aerospace manufacturers worldwide.', 'SUMMARY'),
  ('note-ENG-016', 'Notes', 'BS Materials Engineering', 'EV battery supply chain (South Korea, Germany, USA) and semiconductor materials demand are key growth drivers. BLS classifies under Materials Engineers; median ~$100k USA. Philippines Washington Accord 2023 membership aids recognition.', 'Focus your thesis on battery materials (lithium-ion cathode/anode) or semiconductor process materials — these are the two highest-demand specializations globally for materials engineers through 2030.', 'SUMMARY'),
  ('note-ENG-018', 'Notes', 'BS Mechatronics Engineering', 'One of the most globally transferable engineering degrees; Industry 4.0, EV manufacturing, and logistics automation drive very high international demand. Philippines Washington Accord 2023 aids recognition. Germany average mechatronics salary EUR 93,002/yr.', 'Get a TUV Rheinland or Siemens SIMATIC PLC automation certification — these industry-standard credentials are recognized by manufacturers worldwide and dramatically speed up job placement.', 'SUMMARY'),
  ('note-ENG-019', 'Notes', 'BS Mechatronics Engineering Technology', 'Applied counterpart to the 5-year BS Mechatronics Engineering; treated as technician/technologist level in many countries. Stronger domestic and Gulf market traction than some other 4-year technology degrees.', 'Earn a Siemens SITRAIN or FESTO Didactic automation technician certification to supplement the degree and gain international technician-level recognition in Gulf and European manufacturing.', 'SUMMARY'),
  ('note-ENG-021', 'Notes', 'BS Mining Engineering', 'Australia demand VERY HIGH with 17.1% projected employment growth through 2028; critical minerals (lithium, cobalt, rare earths) driving supercycle demand. AUSiMM assessment pathway available. Average Australian mining engineer salary AUD 147,850—250,000+. Philippines Washington Accord 2023 aids recognition.', 'Pass the PRC Mining Engineer board then immediately apply for Engineers Australia skills assessment under Sustainable Development pathway — this is the fastest route to Australian PR via the 189 visa.', 'SUMMARY'),
  ('note-ENG-022', 'Notes', 'BS Petroleum Engineering', 'BLS median petroleum engineer $141,280 (May 2024); top 10% exceed $228,790. Saudi Aramco offers $80,000—200,000+ range. Highest-paid starting engineering salary in USA per NACE data ($100,750 avg starting). Career sensitive to oil price cycles.', 'Join SPE Philippines student chapter and get your first SPE membership funded — the SPE network is how most petroleum engineering jobs worldwide are filled, especially in the Gulf.', 'SUMMARY'),
  ('note-ENG-023', 'Notes', 'BS Robotics Engineering', 'Fastest-growing engineering specialization globally; robotics demand spans manufacturing automation, surgical robotics, autonomous vehicles, logistics, and defense. Philippines Washington Accord 2023 aids recognition.', 'Build an open-source ROS project on GitHub and compete in regional robotics competitions — international companies (ABB, FANUC, Boston Dynamics) actively recruit from competition results and GitHub portfolios.', 'SUMMARY'),
  ('note-ENG-024', 'Notes', 'BS Sanitary Engineering', 'Australia average sanitary engineer salary AUD 139,376/yr (up to AUD 169,899 in Sydney per ERI 2025). Strong alignment with WHO/UNICEF WASH programs in developing regions. Growing demand from climate-related water infrastructure investment.', 'Supplement your PRC license with a WHO-recognized WASH (Water, Sanitation, and Hygiene) specialist certification to open doors to UN agencies, ADB, and World Bank-funded water projects globally.', 'SUMMARY'),
  ('note-ENG-025', 'Notes', 'BS Structural Engineering', 'Gulf giga-projects (NEOM, Saudi Vision 2030, Dubai Expo legacy) sustain high demand for structural engineers. UK CEng pathway via IStructE. Australia Skilled Independent 189 pathway. USA PE exam required for licensure. Philippines Washington Accord 2023 aids recognition.', 'Become proficient in ETABS and SAP2000 and pursue an IStructE (Institution of Structural Engineers) Associate Membership — this UK credential is recognized across the Gulf and Commonwealth countries.', 'SUMMARY'),
  ('note-HLT-005', 'Notes', 'BS Nursing', 'Most globally portable healthcare credential. USA EB-3 backlog 5-7 years as of 2026. UK fastest Western pathway 4-8 months. Gulf fastest overall 3-6 months. NCLEX pass rate for PH nurses ~35-42% under NextGen format.', 'Start CBT prep before graduation. If targeting USA, deploy Gulf first to save while waiting for EB-3 visa.', 'SUMMARY'),
  ('note-HLT-003', 'Notes', 'BS Medical Technology', 'USA projects 11% lab job growth through 2032. ASCPi exam at Pearson VUE Manila. Gulf fastest at 3-6 months. Australia AUD 78k-135k average among highest globally.', 'Start 1 year post-graduation lab experience immediately - required for ASCPi. Gulf deployment fastest while building toward USA/Australia.', 'SUMMARY'),
  ('note-OTH-008', 'Notes', 'Doctor of Medicine', 'Highest ceiling of any health course ($200k-$600k USA attending) but 5-10 years post-graduation. Gulf allows immediate specialist practice without re-residency. Best IMG specialties for USA: IM, FM, Psychiatry, Pathology.', 'Start USMLE Step 1 prep in 3rd-4th year. If already a specialist, Gulf is fastest high-income route. Target Internal Medicine or Family Medicine for best IMG match rates.', 'SUMMARY'),
  ('note-HLT-009', 'Notes', 'BS Physical Therapy', 'BLS projects 17% US job growth through 2033. FCCPT evaluation takes ~26 months - start immediately after graduation. As of April 2026 EB-2 is current for Philippines PTs, faster than nursing EB-3.', 'Submit FCCPT application the same week you receive your PRC license. Gulf deployment fastest while FCCPT processes.', 'SUMMARY'),
  ('note-HLT-007', 'Notes', 'BS Occupational Therapy', 'Less competition than PT despite similar demand - strategic advantage. WFOT-accredited PH school required. EB-2 current for Philippines OTs as of April 2026. Australia NDIS created massive sustained demand.', 'Verify your school is WFOT-accredited at wfot.org BEFORE enrolling. Paediatric OT (autism) is highest demand specialization globally.', 'SUMMARY'),
  ('note-ENG-005', 'Notes', 'BS Chemical Engineering', 'Oil & gas, petrochemicals, pharma manufacturing globally. Gulf oil & gas largest OFW employer. USA BLS median $108k. Philippines Washington Accord member 2023.', 'For Gulf deployment, have PRC license DFA-authenticated within 3 months of board exam. For USA/Canada/AU, start CDR or PE exam prep early.', 'SUMMARY'),
  ('note-ENG-009', 'Notes', 'BS Electronics Engineering', 'Semiconductor supercycle driving demand in Taiwan, South Korea, Japan, Germany, Netherlands. TSMC, Samsung, Intel, ASML top employers. Philippines Washington Accord 2023 - mutual recognition in 21 countries.', 'Specialize in semiconductor process, VLSI design, or RF/communications. Taiwan (TSMC/MediaTek) fastest-growing destination with high starting salaries relative to cost of living.', 'SUMMARY'),
  ('note-ENG-006', 'Notes', 'BS Civil Engineering', 'Largest OFW engineer category. Gulf mega-projects (NEOM, UAE giga-projects) driving massive demand. Australia has documented skills shortage. NZ Green List gives streamlined PR pathway.', 'Get PRC CE license DFA-authenticated immediately. Structural and project management specializations command highest Gulf salaries.', 'SUMMARY'),
  ('note-ENG-017', 'Notes', 'BS Mechanical Engineering', 'Broad industrial demand globally. Germany EV sector grew engineering jobs 15% in 2024. USA BLS median $102k. Gulf oil & gas facilities strong demand for process/facilities MEs.', 'HVAC, piping, or oil & gas plant design specializations maximize Gulf salary. For Germany, pursue EU Blue Card - PR possible in as few as 21 months.', 'SUMMARY'),
  ('note-ENG-012', 'Notes', 'BS Geodetic Engineering', 'Australia projects 2,000-person surveyor deficit by 2029 - VERY HIGH demand. AUD 142k average with FIFO/mining premium up to AUD 200k. UAE construction boom strong for Filipino geodetic engineers.', 'Australia is the highest-value destination - average $142k and surveyor shortage until at least 2029. Start Engineers Australia CDR immediately after board exam.', 'SUMMARY'),
  ('note-ENG-020', 'Notes', 'BS Metallurgical Engineering', 'EV battery supply chain (lithium, nickel, cobalt hydrometallurgy) is new growth driver. Australia and Canada mining most accessible. Norway highest paying. AusIMM is key professional pathway for Australia.', 'Hydrometallurgy specialization (lithium/nickel processing for EV batteries) is fastest-growing premium skill globally - learn this alongside your degree.', 'SUMMARY'),
  ('note-SCI-009', 'Notes', 'BS Geology', 'Norway highest paying for petroleum geologists ($125k average). Australia critical minerals boom drives mining geologist demand. Canada has strong petroleum geology in Alberta. VETASSESS pathway (not Engineers Australia) for AU assessment.', 'Petroleum geology or mining geology specialization pays 3x environmental geology. Build GIS and remote sensing skills - universally required for international geology roles.', 'SUMMARY'),
  ('note-BUS-001', 'Notes', 'BS Accountancy', 'ASEAN MRA activated Jan 2025 - Philippine CPAs can register as RFPA in Singapore/Thailand/ASEAN. US CPA exam now available in Philippines since July 2024. UAE fastest deployment (1-2 years). Big 4 intracompany transfer is most reliable USA/UK/AU pathway.', 'Start US CPA exam preparation in 3rd year - you can now sit exams in Manila. For UAE/Singapore, ACCA or CPA credential opens doors significantly faster.', 'SUMMARY'),
  ('note-TEA-003', 'Notes', 'BS Secondary Education', 'UK QTS now free for eligible overseas teachers from August 2025 - significant change. NZ Green List covers secondary teachers to PR. STEM subject teachers in highest demand globally. Korea E-2 visa explicitly EXCLUDES Filipino citizens.', 'Specialize in Math, Science, or SPED - these subjects command premium demand globally. Apply for UK QTS before departure to streamline school sponsorship.', 'SUMMARY'),
  ('note-OTH-003', 'Notes', 'BS Criminology', 'Philippine RCrim license does NOT qualify for direct foreign police entry - citizenship required. International pathways: private security management (Gulf), forensic science (USA/AU/UK), corrections (Canada/Australia), digital forensics (global/remote). ASIS CPP/PSP certifications are globally portable.', 'PH Criminology license alone won''t get you international policing. Target either security management (ASIS CPP certification) or forensic science (additional lab credentials).', 'SUMMARY'),
  ('note-MAR-001', 'Notes', 'BS Merchant Marine Officer (Naval Architecture / Marine Transportation)', 'Philippines supplies 25-30% of global seafarers (~488,606 deployed Oct 2024). Most structured OFW pathway - manning agencies handle deployment. STCW White List maintained. OFW seafarers exempt from PH income tax on foreign earnings.', 'Specialize in LNG/gas carriers or offshore (DP certification) for 30-40% salary premium over bulk carriers. Enroll with MARINA-accredited school and start cadetship immediately upon graduation.', 'SUMMARY'),
  ('note-OTH-013', 'Notes', 'BS Agriculture', 'Philippine Agriculturist license has no bilateral mutual recognition internationally. Semi-skilled OFW programs (Japan SSW, Israel bilateral) do NOT leverage the degree. Graduate-level international roles require master''s degree or food safety certifications (HACCP, ISO 22000).', 'Add HACCP and ISO 22000 food safety certifications - these are internationally portable and open UAE/Saudi QA roles paying $2,200-$4,100/month. Japan SSW pays ~$1,100-$1,450/month and doesn''t leverage your degree.', 'SUMMARY'),
  ('note-OTH-011', 'Notes', 'BS Fisheries Technology', 'BS Fisheries is primarily a domestic career track. PRC Fisheries Technologist license has no bilateral mutual recognition internationally. Most OFW placements are fish processing factory workers (degree not leveraged). Best route is seafood QA/food safety in Middle East or aquaculture science in Australia.', 'Add HACCP, ISO 22000, and MSC Chain of Custody certifications. These are more internationally portable than your PRC Fisheries license and open UAE/Saudi seafood QA roles paying $1,360-$3,270/month.', 'SUMMARY'),
  ('note-HLT-001', 'Notes', 'Doctor of Dental Medicine', 'Gulf (Saudi, UAE, Qatar) accepts PH DMD with DataFlow + Prometric exam. Australia requires ADC written + practical exam (multi-year process). UK requires ORE (Overseas Registration Exam) via GDC. Strong demand in Gulf under Vision 2030 hospital expansions. USA pathway extremely difficult — requires re-doing a US dental program.', 'Target Gulf countries first for fastest entry; pursue ADC/GDC route for long-term settlement in Australia or UK.', 'SUMMARY'),
  ('note-HLT-002', 'Notes', 'Doctor of Optometry', 'Very limited OFW pathway. USA requires graduation from ACOE-accredited optometry school (US or Canada only) — PH OD degree not recognized. Canada requires International Optometry Bridging Program (IOBP). UK (GOC) considers PH OD if post-baccalaureate equivalent. Gulf countries (Kuwait, UAE, Saudi) accept OD with DataFlow + Prometric exam but volume is low. Most PH optometry graduates practice domestically. Papua New Guinea and Palau have small but open markets.', 'If international practice is your goal, consider Gulf countries via DataFlow; for USA/Canada you effectively need to re-study.', 'SUMMARY'),
  ('note-HLT-004', 'Notes', 'BS Midwifery', 'PH midwifery is a distinct BS degree (4 years) but most destination countries recognize it within a midwifery-nursing framework. UK (NMC) has a dedicated midwife register and actively recruits internationally. Gulf countries (Saudi, UAE) recruit under nursing-midwife classification. Australia (ANMAC) has strict midwifery standards and may require bridging. PH midwives often retrain as nurses (BSN) abroad to access wider job markets. Ireland has active midwifery shortage.', 'Target UK NHS direct recruitment for best pay and PR pathway; consider upskilling with BSN for wider Gulf options.', 'SUMMARY'),
  ('note-HLT-006', 'Notes', 'BS Nutrition and Dietetics', 'Philippines has a formal CDR (Commission on Dietetic Registration) Reciprocity Agreement with the USA — RND holders with 2 years experience can take the US RD Exam (CDR). This is a significant advantage. Canada requires credential evaluation + Dietetic Qualifying Exam. Australia requires DAA accreditation or bridging. Gulf countries recruit clinical dietitians for hospitals. Growing demand globally driven by diabetes, obesity, and aging populations.', 'The PRC-CDR Reciprocity Agreement is a unique advantage — prioritize 2 years of post-licensure experience to qualify for US RD exam pathway.', 'SUMMARY'),
  ('note-HLT-008', 'Notes', 'BS Pharmacy', 'Strong international pathway in all major English-speaking countries and Gulf. Canada PEBC now allows international graduates to skip Evaluating Exam (from May 2025) if eligible. UK requires OSPAP (1-year accredited course) then GPhC registration. Australia requires OPRA exams (written + OSCE) then AHPRA registration. Gulf (Saudi, UAE, Qatar, Kuwait) recruits directly with DataFlow + Prometric. Pharmacist demand rising globally due to aging populations and clinical pharmacy expansion.', 'Canada is fastest international route with highest pay; Gulf is fastest deployment with tax-free income.', 'SUMMARY'),
  ('note-HLT-010', 'Notes', 'BS Public Health', 'No PRC board exam means no formal credential benchmark, but this also means international mobility is largely based on degree quality and experience. Entry-level international roles typically require MPH or equivalent. Strong demand in global health orgs (WHO, UNICEF, CDC, MSF), government health agencies, and NGOs. USA (CDC PHAP fellowship), Canada (PHAC), Australia (DoH) all hire public health professionals. Singapore MoH actively recruits for epidemiology and policy roles. Career ceiling is high with MPH + experience.', 'Pursue an MPH (preferably at UP Manila or a US/AU/UK university) to unlock senior international roles; build experience in DOH or NGOs first.', 'SUMMARY'),
  ('note-HLT-011', 'Notes', 'BS Radiologic Technology', 'Strong OFW pathway. Gulf (Saudi, UAE, Qatar, Kuwait) has very high demand for radiographers/RadTechs under hospital expansion programs. ARRT (USA) is the gold standard credential — PH graduates can apply but must meet education equivalency. AHPRA registration in Australia requires degree equivalency + IELTS. UK requires HCPC registration via SCoR (Society of Radiographers) credentialing. Modality specialization (CT, MRI, Ultrasound, Nuclear Medicine) dramatically increases earning power.', 'Target Gulf for fastest deployment and tax-free income; pursue ARRT certification for the highest long-term earning potential in USA.', 'SUMMARY'),
  ('note-HLT-012', 'Notes', 'BS Respiratory Therapy', 'Respiratory therapy is a growing specialty globally, accelerated by COVID-19 increasing awareness. USA has the most structured path via NBRC (National Board for Respiratory Care) — CRT then RRT credentials. Canada has CSRT (Canadian Society of Respiratory Therapists) national exam. Gulf (Saudi, UAE, Qatar, Kuwait) has strong demand due to high prevalence of respiratory conditions (smoking, air quality). UK path via HCPC. BLS projects 12% job growth for RTs through 2034.', 'USA offers highest salaries with strong demand; Gulf is fastest deployment option; pursue NBRC RRT for maximum US earning potential.', 'SUMMARY'),
  ('note-HLT-013', 'Notes', 'BS Speech and Language Pathology', 'SLP is one of the fastest-growing allied health professions globally. USA (ASHA CCC-SLP) is the premium destination with median salary of $95k-107k/year. Australia has strong demand and SPA provides clear registration pathway. Canada SAC certification + provincial licensing. UK HCPC registration. Gulf (UAE, Saudi Arabia) has rapidly growing demand especially in pediatric autism and dysphagia. Bachelor''s degree opens doors but Master''s (in USA, Canada) is standard entry for full ASHA certification. PH''s 4-year BS SLP is recognized in most countries.', 'USA offers the highest salary; consider completing a US MS-SLP program for ASHA CCC-SLP certification, or target Australia for fastest PR pathway.', 'SUMMARY'),
  ('note-OTH-007', 'Notes', 'BS Medical Biology', 'BS Medical Biology is primarily a pre-med/research track in PH. No PRC board exam creates both challenge (no credential benchmark) and flexibility (careers in research, biotech, pharma, public health). International career paths are via: (1) graduate school (MS/PhD) in USA, UK, Germany, Australia; (2) research assistant/lab technician roles; (3) biotech/pharma industry jobs; (4) medical school (MD/MBBS) abroad. Direct OFW deployment is rare — this is an education-first, career-second path. USA and UK have the most developed biotech industries. Germany has strong pharmaceutical industry (Bayer, BASF, Merck KGaA).', 'Treat BS Medical Biology as a launch pad: either pursue MD (medicine) locally or abroad, or get an MS/PhD scholarship at a foreign university to enter biotech/pharma research.', 'SUMMARY'),
  ('note-OTH-014', 'Notes', 'BS Veterinary Medicine (DVM/VMD)', 'Veterinarian shortage is acute and global — Australia, NZ, UK, Canada, and USA all have active shortages. PH DVM is typically assessed by AVBC for AU/NZ. UK accepts via RCVS assessment and may require additional training period. Canada and USA require NAVLE (North American Veterinary Licensing Examination). New Zealand has vet on the Green List (critical shortage). Australia has TSS visa (482) actively used. Strong PR pathways in all major destinations. Large-animal vets are most needed; companion animal vets are more competitive in urban areas.', 'New Zealand and Australia offer the fastest path given the critical shortage — target large/mixed animal practice for maximum demand and incentive packages.', 'SUMMARY'),
  ('note-IT-001', 'Notes', 'BS Computer Science', 'CS is the single most internationally mobile non-healthcare Philippine degree. Three parallel tracks exist: (1) Remote work from PH for US/EU employers — no relocation, USD/EUR rates; (2) Singapore/Gulf deployment — fastest physical relocation; (3) USA/Canada/Australia — highest ceiling but longer process. The Philippines IT-BPM industry (PEZA-registered BPOs and GICs) also absorbs large numbers; distinguish between working FOR a foreign company locally (IT-BPM) vs. BEING foreign-deployed. Remote work is increasingly the primary ''international'' pathway without physically moving.', 'Build a GitHub portfolio while still in school. Contribute to open-source. Get one cloud cert (AWS Solutions Architect Associate) before graduation. These three things unlock remote work within 3-6 months of graduation and bypass the entire visa-and-sponsorship system.', 'SUMMARY'),
  ('note-IT-002', 'Notes', 'BS Cyber Security', 'Cybersecurity is experiencing a global workforce shortage of 3.5 million unfilled positions (ISC2 2024 Workforce Study). Unlike general software development, cybersecurity roles are less susceptible to AI replacement and often require government security clearances (USA, Australia, UK) or industry certifications that are globally standardized. Filipino BS Cybersecurity graduates are entering a field where demand dramatically outpaces supply. The three pillars: certifications (CompTIA Security+, CISSP, CEH), hands-on lab experience (TryHackMe, HackTheBox), and portfolio (CTF wins, bug bounty finds). Government/defense sector pays premium but requires citizenship in most Western countries.', 'Start TryHackMe or HackTheBox in Year 1. Get CompTIA Security+ BEFORE graduation — it is the global entry-level standard and requires no experience. CEH (Certified Ethical Hacker) needs 2 years experience but looks excellent on a resume. CISSP requires 5 years but is the gold standard for management tracks.', 'SUMMARY'),
  ('note-IT-003', 'Notes', 'BS Game Development and Animation / Entertainment and Multimedia Computing', 'This is the most portfolio-dependent IT cluster. Employers hire the demo reel and portfolio, not the degree. Philippine animation industry is a genuine springboard — the Philippines has a long history of animation outsourcing (animation for Warner Bros, Nickelodeon, Disney, DreamWorks produced in Manila). This creates a unique pathway: work in Philippine animation studio for 2—3 years, build credits on internationally recognized shows, then apply to international studios. Game development pathway is different — dominated by indie/mobile game scene in PH; AAA studio employment requires relocation to Canada, USA, or Japan. Three parallel tracks: (1) Animation: PH studio credits ? international studio; (2) Game dev: mobile/indie remote ? AAA studio relocation; (3) VFX/CG: PH VFX work (Synergy88, Toon City, Cloudpunk) ? international post-production.', 'Your portfolio IS your resume. Get it on ArtStation (animation/VFX) or itch.io (game dev). Join Global Game Jam (annual, January) to build a portfolio game with a team. For animation, learn Autodesk Maya, Blender, and Toon Boom Harmony — the industry trifecta. For game dev: Unity or Unreal Engine is mandatory; C# for Unity, C++ for Unreal.', 'SUMMARY'),
  ('note-IT-004', 'Notes', 'BS Information Technology', 'BS IT is the most commonly enrolled tech degree in the Philippines (hundreds of thousands of graduates annually) and has the broadest scope — it covers systems administration, networking, database management, business analysis, IT project management, and application development. The challenge is differentiation: BS IT is a generalist degree in a market that increasingly rewards specialization. The three best strategies for BS IT internationally: (1) Specialize early in cloud (AWS/Azure) — cloud skills are globally portable and immediately employable; (2) Add PMP or CAPM for project management track — opens IT-BPM leadership roles globally; (3) Pair with CISA for IT audit/governance track — opens Big 4 advisory roles internationally. BS IT graduates must understand: the degree alone does not command premium international salaries the way BS CS or specialized cybersecurity does. Certifications and demonstrated skills are mandatory differentiators.', 'Get AWS Solutions Architect Associate before graduation. It costs $300 to take but unlocks cloud roles starting at $60k remotely. CompTIA Network+ and CompTIA A+ are entry-level but widely recognized. For the IT-BPM/management track: ITIL 4 Foundation (service management) and PMP (project management) are the two most valuable certs for IT management internationally.', 'SUMMARY'),
  ('note-IT-005', 'Notes', 'BS Library and Information Science', 'Library and Information Science has the narrowest international career pathway of all five IT courses — but niche real opportunities exist. The key distinction for LIS internationally: traditional librarianship (managing physical collections) vs. information management/knowledge management (digital, corporate, research settings). Digital transformation of libraries globally and the growth of knowledge management, corporate libraries, and information architecture roles create demand for LIS-trained professionals in non-traditional settings. The Middle East Gulf states (Saudi Arabia, UAE, Qatar) are the most accessible international destination for PRC Librarians — university libraries and corporate information centers in Gulf actively hire Filipino librarians. USA requires a Master''s of Library Science (MLS) from an ALA-accredited program for most professional roles — the BS LIS is not sufficient for US librarian positions. UK requires CILIP certification for Chartered Librarian status. International organizations (UN, World Bank, IMF, ADB) hire information professionals — highly competitive but real. Modern LIS graduates who develop data analytics, metadata/taxonomy, UX for digital libraries, and knowledge management skills have stronger international marketability than traditional cataloging-focused graduates.', 'The PRC Librarian License is your entry credential for the Middle East pathway. For USA/UK/Australia, you will need a master''s degree — either complete an MLS in the Philippines or pursue it abroad. Pivot toward information architecture, digital asset management, and knowledge management skills — these cross into corporate settings and pay significantly more than traditional library roles. The SLA (Special Libraries Association) has active Philippine chapter connections.', 'SUMMARY'),
  ('note-MID-001', 'Notes', 'BS Agribusiness', 'Agribusiness has better international mobility than pure Agriculturist because it combines business/management skills with agricultural knowledge. The key differentiator from a pure agriculture degree is the supply chain, commodity trading, and agri-finance competency. The Netherlands is the global hub for agrifood innovation — Wageningen University & Research (WUR) is ranked #1 globally for Agriculture and Forestry; Dutch agribusiness companies (Rabobank, FrieslandCampina, Unilever Food, Yara International fertilizers) hire agribusiness graduates. Canada has growing agrifood sector with immigration pathways through Saskatchewan, Manitoba, and Alberta agricultural programs. Australian ACIAR research collaborations sometimes hire Filipinos for project-based roles. For domestic graduates: the biggest multinationals in PH agribusiness (Del Monte, Dole, San Miguel Agri, Jollibee Foods procurement, ANFLO Group) offer competitive corporate careers. Commodity trading is an underexplored pivot — major trading houses (Cargill, Louis Dreyfus, Olam) hire Filipino agribusiness graduates for grain/sugar/coconut oil trading desk analyst roles.', 'The Wageningen University MSc program in Management of Agro-Food Chains is the gold standard for international agribusiness careers. Apply for the NFP (Netherlands Fellowship Programme) scholarship for Filipino government employees, or Orange Knowledge Programme (OKP). If going to industry directly, Cargill Philippines, San Miguel Foods, and Del Monte Philippines are strong employers with international transfer potential. For commodity trading, study CFA (Chartered Financial Analyst) alongside your degree.', 'SUMMARY'),
  ('note-MID-002', 'Notes', 'BS Agro-Forestry', 'Agro-Forestry is a highly specialized field with limited direct international employment pathways at the bachelor''s level. The international career requires a Master''s degree — ideally from Wageningen (Netherlands), University of Copenhagen, or ANU (Australia). The main international employers are CGIAR (Consultative Group on International Agricultural Research) system organizations, particularly CIFOR-ICRAF (the merged Center for International Forestry Research and World Agroforestry). ICRAF''s Bogor, Indonesia facility is relatively accessible for Filipino graduates. FAO''s forestry programs in Rome and regional offices hire agroforestry specialists. Domestically, DENR''s Forest Management Bureau, DA''s National Agro-Forestry Program, and UPLB-based research are the entry points. Carbon offset/REDD+ programs are a growing pathway — agroforestry systems are used for carbon sequestration projects financed by international carbon markets. This is an emerging area with real income potential in climate finance.', 'A Master''s degree is essentially mandatory for meaningful international career progression in this field. Apply for CGIAR internship programs early — CIFOR-ICRAF hosts graduate students and interns from UPLB and CLSU regularly. The REDD+ / carbon offset angle is your fastest-growing pathway without a Master''s — voluntary carbon market developers (South Pole, Verra, Gold Standard) hire agroforestry specialists to design and verify tree-planting projects. FAO Junior Professional Officer (JPO) programs open doors after 2-3 years of experience.', 'SUMMARY'),
  ('note-MID-003', 'Notes', 'BS Climate Change / Climate Change Adaptation', 'Climate Change as a degree is relatively new but the career demand is explosively growing. The Glasgow COP26 (2021), Dubai COP28 (2023), and Baku COP29 (2024) commitments created billions in new climate finance flows requiring professional management. The Green Climate Fund (GCF) in Incheon, South Korea is the world''s largest dedicated climate fund ($13.6B pledged) and actively hires climate professionals from developing countries — including Filipinos. ESG (Environmental, Social, Governance) consulting is the fastest-growing career track in global finance and management consulting — major firms (McKinsey, BCG, Deloitte, PwC, EY) have massive sustainability practices. Singapore is Asia''s ESG hub with MAS (Monetary Authority of Singapore) driving sustainable finance regulations. The Philippines itself is uniquely positioned — as one of the most climate-vulnerable countries globally, PH has exceptional credibility in international climate negotiations. PAGASA, CHED Climate Change programs, CCC (Climate Change Commission), and NEDA environmental division are domestic entry points.', 'Get your CFA ESG Certificate ($355, online exam) — it is increasingly required for ESG finance roles. Learn to use climate modeling tools (QGIS for mapping, R for climate data analysis, or Python). The GCF in South Korea runs competitive internship programs specifically for developing country nationals — apply in your 3rd or 4th year. Singapore''s MAS Green Finance programs are actively recruiting climate-trained professionals across Southeast Asia. A Master''s in Climate Change Policy (UK: Oxford, Edinburgh, UCL) or Environmental Management (NUS Singapore) significantly upgrades your trajectory.', 'SUMMARY'),
  ('note-MID-004', 'Notes', 'BS Data Science and Analytics', 'Data Science and Analytics is one of the most internationally mobile degrees available today, with the added benefit of massive remote work potential. Unlike most other careers in this research, Data Scientists can command international salaries while physically remaining in the Philippines — remote-first companies (fully remote startups, US tech companies with offshore teams, UK fintech firms) regularly hire Filipino data scientists at USD 24,000-60,000+/year, far exceeding comparable local salaries. In-person migration destinations are led by the USA (Silicon Valley, NYC fintech, Seattle tech), Singapore (Asia''s tech hub, data-intensive fintech/logistics/government), and UK (London fintech, Edinburgh financial analytics). Australia has strong demand in mining analytics, financial services, and health data. Canada''s tech corridor (Toronto-Waterloo, Vancouver) is accessible via Express Entry. The Philippine domestic market is also growing rapidly — BPO industry evolving to data analytics services, DICT programs, and multinational Philippine data centers. Key insight: this is the only degree in this entire research where the remote work pathway genuinely rivals or exceeds the migration pathway in early-career compensation.', 'Build a GitHub portfolio immediately — every project counts. Join Kaggle competitions to demonstrate skills publicly. The remote work pathway is your fastest route to international compensation without migrating: Philippine-based Filipino data scientists working for US startups routinely earn PHP 100,000-200,000/month. For Singapore, the MAS TechUp initiative and MoneySense fintech programs create data science demand. For USA, H-1B is challenging (lottery) but employer-sponsored options exist for specialist roles. The cloud certification (AWS/GCP) costs $300-600 and dramatically increases your hirability globally.', 'SUMMARY'),
  ('note-MID-005', 'Notes', 'BS Disaster Risk Management (DRRM)', 'DRRM is a field where Philippine graduates have genuine competitive advantages internationally — the Philippines is one of the world''s most disaster-prone countries and among the most experienced in disaster response. Filipino DRRM practitioners have real-world expertise that is highly credible in international organizations. However, the career path has a clear pattern: most meaningful international roles (OCHA, UNDP, IFRC at operational level) require 3-5 years of domestic/field experience first. Entry-level international positions are competitive and relatively few. The humanitarian sector uses a ''humanitarian system'' of career ladders: internship ? junior professional officer (JPO, typically government-sponsored) ? national professional officer (NPO) ? international professional. The fastest domestic entry is via NDRRMC, LGU DRRM offices, OCD (Office of Civil Defense), DSWD emergency response, or Philippine Red Cross. Climate change is accelerating demand — the IPCC estimates DRR-related employment needs will grow significantly through 2030. Typhoon, earthquake, and flooding response expertise from the Philippines is genuinely valued globally.', 'Work with Philippine Red Cross or a local DRRM office first — 2-3 years of documented field experience is what separates you from international competitors. The OCHA Field Coordination Training Programme (FCTP) is a key credential. Sphere Handbook knowledge is expected. Learn GIS (QGIS/ArcGIS) for disaster risk mapping — it is increasingly required. Japanese ADRC in Kobe runs fellowships specifically for Asian DRRM practitioners. The JPO (Junior Professional Officer) programme is the main UN entry pathway — DOST/DILG Philippines sponsors nominees.', 'SUMMARY'),
  ('note-MID-006', 'Notes', 'BS Renewable Energy', 'Renewable Energy is among the fastest-growing global employment sectors. IEA (International Energy Agency) estimates 30 million jobs in renewable energy globally by 2030, up from 13.7 million in 2023. The energy transition is a structural, decade-long megatrend creating sustained demand. Australian Clean Energy Council accreditation is relatively accessible for Filipino RE graduates and Australia has the fastest RE deployment per capita globally. Germany''s Energiewende (energy transition) has created the world''s largest renewable energy workforce with specific technical roles. Taiwan is a major market for offshore wind energy, with companies like Orsted, Vestas, and Jan De Nul operating offshore wind farms and recruiting engineers. USA''s Inflation Reduction Act (IRA) — $369B in clean energy spending — is the single largest driver of RE employment globally. Key specializations with highest demand: solar PV design/installation project management, offshore wind engineering, energy storage systems (battery), and grid integration. Philippines domestic opportunity: DOE RE Act (RA 9513) mandates 35% RE share by 2030, creating significant local demand through private energy developers (Solar Philippines, ACEN, Vena Energy, Total Energies Philippines).', 'NABCEP PV Associate certification ($375) is widely recognized in solar globally. For Australia, apply for Clean Energy Council accreditation — it is required to certify solar installations and creates direct employment. The IRA has made USA one of the best RE job markets in history — apply through companies like First Solar (thin-film), NextEra Energy (largest US renewable company), or Nextracker. Germany''s DAAD has specific fellowships for energy transition studies. Taiwan is actively recruiting offshore wind engineers with the government''s push to install 20GW offshore wind by 2035.', 'SUMMARY'),
  ('note-OTH-012', 'Notes', 'BS Forestry', 'BS Forestry with PRC Forester License primarily serves the domestic Philippine market — DENR and PAWB (Protected Areas and Wildlife Bureau) are the primary employers, along with the forestry sector of large landowners, plantation forestry companies, and wood processing industries. International career pathways exist but are distinctly specialized. ITTO in Yokohama specifically funds fellowships for developing country foresters. FAO''s Forestry Division in Rome employs tropical forestry specialists and Filipinos with DENR experience and ITTO fellowship backgrounds have been placed there. FSC (Forest Stewardship Council) chain-of-custody auditing is an internationally portable certification — FSC-certified auditors can work anywhere globally assessing sustainable forestry, timber supply chains, and pulp/paper operations. Canada''s RPF (Registered Professional Forester) designation is achievable with credential equivalency and there is active demand in BC and Alberta. Conservation NGOs (WWF, WCS, TNC, Wildlife Conservation Society) hire foresters for protected area management, REDD+ programs, and biodiversity offset projects. The carbon market angle is growing — tropical forests are major carbon sinks and REDD+ projects require forester verification expertise.', 'Pass the PRC Forester board and get at least 2 years DENR/PAWB fieldwork. Then pursue FSC Lead Auditor training ($500-1,000 course + assessment) — this makes you internationally deployable as a forestry auditor. ITTO''s fellowship program is specifically designed for Filipino forestry graduates — apply for the Young Expert and Fellowship programs. For REDD+ carbon projects, learn VCS (Verified Carbon Standard) methodology and MRV (Measurement, Reporting, Verification) techniques — this combination of Forester license + REDD+ expertise is what gets you hired by conservation organizations and carbon project developers globally.', 'SUMMARY'),
  ('note-SCI-001', 'Notes', 'BS Applied Mathematics', 'Applied Mathematics is one of the most internationally transferable science degrees. The key pivot: the degree title matters less than demonstrated skills. Most successful international hires from this course work as Data Scientists, Quantitative Analysts, Actuarial Analysts, Operations Research Analysts, or Software Engineers. Pure mathematician roles abroad are almost exclusively PhD-track. With a BS and programming skills (Python, R, SQL), direct employment in tech and finance internationally is very achievable, including remote-first roles. Singapore and UK have formal visa categories for mathematical sciences occupations. USA is the highest-ceiling destination but requires H-1B sponsorship (lottery). Remote work for US or EU tech companies is the fastest entry point for fresh graduates.', 'Learn Python and SQL before graduation. Build a Kaggle portfolio or GitHub repo. Apply directly to Singapore-based fintech or tech companies (no lottery system unlike USA). Actuarial science is a natural adjacent career: passing CAS or SOA actuarial exams (done in Philippines) dramatically opens USA, Canada, and Bermuda insurance markets.', 'SUMMARY'),
  ('note-SCI-002', 'Notes', 'BS Applied Physics', 'Applied Physics has a real industry pathway through the global semiconductor and medical device sectors — this distinguishes it from pure theoretical physics. The key employers internationally are semiconductor fabs (TSMC, Samsung, ASML, SK Hynix, Intel) and medical device companies (Medtronic, Philips, Siemens Healthineers). Most BS-level roles are process engineer, R&D technician, quality engineer, or equipment engineer — not physicist roles per se. A master''s in semiconductor engineering, materials science, or photonics significantly accelerates access. The Netherlands is notable because ASML (the world''s monopoly maker of EUV lithography machines) is headquartered in Eindhoven and actively recruits globally. South Korea and Taiwan are the fastest entry points because their semiconductor fabs directly recruit Filipinos for technician and process roles. Purely academic or research physics roles (CERN, NIST, national labs) require a PhD.', 'Specialize in semiconductor physics, optics, or medical imaging during your electives. Learn Python or MATLAB for data analysis. Taiwan''s Gold Card visa actively targets STEM professionals: apply after 2 years of relevant experience. ASML in the Netherlands has a graduate program worth targeting. Avoid the academic physicist path unless you want a PhD — industry is where the international BS-level jobs are.', 'SUMMARY'),
  ('note-SCI-003', 'Notes', 'BS Biochemistry', 'HONEST ASSESSMENT: For most international research scientist roles at Big Pharma (Pfizer, Novartis, Roche, AstraZeneca), a master''s or PhD is the de facto requirement. A BS in Biochemistry from the Philippines primarily opens doors in: (1) Pharmaceutical QC or QA analyst roles — these are achievable with a BS and are internationally deployable. (2) Clinical laboratory work — requires additional credentials such as MedTech license or equivalent abroad. (3) Food science or quality assurance in food manufacturing. (4) Career pivot to medical school: BS Biochemistry is excellent pre-med preparation. The most direct international BS-level pathway is QC or QA Analyst at pharmaceutical manufacturing plants, particularly in Ireland (where Pfizer, J&J, Amgen, Lilly all have large manufacturing sites that actively recruit Filipinos) and Singapore (Biopolis biotech hub). Ireland is the single most accessible direct pathway for Filipino biochemistry graduates: multiple pharmaceutical manufacturers and a straightforward Critical Skills permit process.', 'If you want pharma industry internationally: pursue QC or QA or Validation Engineer roles, not research scientist roles — these do not require a PhD and Ireland and Singapore are hiring Filipinos. If you want research: plan for a master''s abroad — fully funded programs exist in Germany, Netherlands, and UK. MedTech license (Philippines) plus biochemistry equals medical lab scientist pathway to Australia, Canada, and UK. Pre-med remains the highest-ceiling career pivot.', 'SUMMARY'),
  ('note-SCI-004', 'Notes', 'BS Applied Statistics', 'BS Applied Statistics is arguably the most internationally employable pure-science degree from the Philippines right now. The global demand for data analysts, data scientists, and statisticians vastly exceeds supply. Filipino graduates with Python, R, SQL, and statistics skills are directly competitive in international and remote job markets without additional credentials. Key roles: Data Analyst, Data Scientist, Business Intelligence Analyst, Biostatistician, Quantitative Researcher, Actuary (with additional exams). The remote-first tech economy means many US and EU companies hire Filipino statisticians on contractor basis — fastest path to international income. Government statistical offices in Canada (Statistics Canada), Australia (ABS), and UK (ONS) all hire statisticians and have immigration pathways. Clinical trials or biostatistics is a niche with very high demand in USA, UK, and Switzerland (pharma sector).', 'Learn Python (pandas, scikit-learn), SQL, and R before graduation. Get a Kaggle competition ranking. Biostatistics is a high-value niche: if you can pair stats with clinical trial methodology (GCP certification is free online), pharma companies in Ireland and Singapore will hire you with a BS. Remote contract work through Toptal or LinkedIn is the fastest way to start earning international rates from the Philippines.', 'SUMMARY'),
  ('note-SCI-005', 'Notes', 'BS Biology', 'HONEST ASSESSMENT: BS Biology is primarily a domestic career in the Philippines — DOST researcher, DENR, academe (instructor), pharmaceutical lab assistant, or pre-med prerequisite. The degree by itself has very limited direct international OFW pathways. The high-value international paths all require either: (1) Medical school (MD) then USMLE for USA, AMC for Australia, PLAB for UK; (2) Graduate school (master''s or PhD) for research roles; (3) Career pivot to MedTech (1-year conversion or dual program) for lab science work abroad; (4) Pharmaceutical sales or medical representative — achievable with BS Biology plus sales skills, active in Gulf, Singapore, and Malaysia. Filipino biology graduates working internationally are overwhelmingly either doctors, nurses (via re-course), MedTechs, or pharma sales reps — not biologists per se. The DOMESTIC tag reflects that the direct BS Biology pathway to OFW work is weak; the pivots are the real pathways.', 'Decide early: pre-med (aim for UP PGH, UERM, or Cebu Doctors), or science research track. If research track, plan for a master''s abroad — DOST-funded scholarships exist. If pharma sales abroad is the goal, pharmaceutical companies in UAE, Singapore, and Malaysia hire Filipino BS Biology graduates as medical representatives — no additional credential needed, but communication skills and product knowledge are key.', 'SUMMARY'),
  ('note-SCI-006', 'Notes', 'BS Botany', 'HONEST ASSESSMENT: BS Botany has the narrowest international career pathway of all courses in this cluster. The degree is primarily domestic: DOST, DENR, PCAARRD, NSCB, or academe. International opportunities exist, but almost all require either (a) a graduate degree (master''s or PhD) for research roles, or (b) a career pivot into allied fields (agriculture, environmental science, ecotourism management). The most realistic international paths for a BS Botany graduate: (1) CGIAR research centers — these are international agricultural research organizations with positions in developing countries, but most research positions require master''s or PhD. (2) Environmental impact assessment consulting in Australia or Canada — possible with additional environmental science training. (3) Seed company or agricultural biotechnology industry (Syngenta, Corteva, Bayer CropScience) — possible with BS in a QA or field technician role, but limited. Pure botanist is not an internationally recruited profession outside academia.', 'Pair botany with GIS (Geographic Information Systems) skills — this pivots you to environmental consulting and land management roles that do exist internationally. Consider master''s programs in Conservation Biology, Agroforestry, or Plant Biotechnology at Wageningen University (Netherlands, globally top in agricultural science) — most programs are in English. CGIAR centers offer internships that convert to staff positions for qualified candidates.', 'SUMMARY'),
  ('note-SCI-007', 'Notes', 'BS Chemistry', 'BS Chemistry with PRC board license has better international deployability than most pure science courses because the industrial chemistry sector (petroleum, petrochemicals, pharmaceuticals, food processing, mining) has real international demand. The Gulf states (UAE, Saudi, Qatar, Kuwait) represent the most accessible immediate destination: petrochemical companies (SABIC, ADNOC, QatarEnergy) and pharmaceutical manufacturing plants hire chemists at BS level. Australia has strong demand in mining or resources chemistry and food safety. Canada''s mining and oil sands sector is another route. Pure research chemistry is dominated by PhD-holders internationally. The PRC license is recognized as a base credential in Gulf states — unlike many Philippine professional licenses, it is actually helpful abroad. The board exam has national pass rates around 30-40%, so the PRC license itself signals competency internationally.', 'Pass the CLE — it matters internationally, especially in the Gulf. Target petrochemical plant QC or QA roles in UAE or Saudi Arabia as a first posting. Gulf experience plus 2-3 years leads to credentialing for Australia (VETASSESS plus skills assessment) or Canada (Express Entry). Royal Society of Chemistry (RSC) membership can be obtained from the Philippines and is recognized in UK and internationally — start the application process early.', 'SUMMARY'),
  ('note-SCI-008', 'Notes', 'BS Environmental Science', 'Environmental Science has genuine and growing international demand driven by: (1) ESG (Environmental, Social, Governance) reporting requirements for corporations globally — demand for environmental auditors and sustainability analysts. (2) Environmental Impact Assessment (EIA) — required for infrastructure projects globally; high demand in UAE and Saudi Arabia and Australia for major construction programs. (3) Climate change consulting and carbon market work. (4) Environmental compliance for mining, oil and gas, and real estate sectors. The most accessible international path for a fresh graduate is Environmental or HSE Officer or EIA Consultant in the Gulf (UAE, Saudi) where massive infrastructure projects (NEOM, Vision 2030) require constant environmental assessment. Canada is the best long-term destination due to its immigration points system favorability for environmental scientists and genuine environmental protection sector. The NEBOSH IGC (International General Certificate — Health, Safety, Environment) is a globally recognized professional certification achievable in the Philippines and dramatically boosts employability internationally.', 'Get NEBOSH IGC certification before graduation or during your first year of work — it costs about PHP 40,000-60,000 but is recognized in UAE, UK, Australia, and Singapore. ISO 14001 Lead Auditor certification is another high-value add. Target EIA consulting firms in UAE as first posting — experience on large infrastructure projects is globally transferable. ESG analyst roles are increasingly remote-friendly.', 'SUMMARY'),
  ('note-SCI-010', 'Notes', 'BS Human Biology', 'HONEST ASSESSMENT: BS Human Biology (offered primarily at UP Diliman and a few other universities) is explicitly designed as a pre-medical degree. The primary pathway is medical school. Direct international employment with a BS Human Biology degree is very limited — the degree is not a recognized profession internationally the way nursing or medical technology is. However, career pivots accessible to Human Biology graduates include: (1) Clinical Research Coordinator (CRC) — growing field as clinical trials increasingly involve Filipino sites and contract research organizations (CROs). ACRP certification (obtainable in Philippines) opens CRC roles in USA, UK, and Singapore. (2) Pharmaceutical sales representative — achievable in Gulf or Singapore with this background. (3) Graduate school in Public Health, Epidemiology, or Biostatistics then international public health roles (WHO, WPRO, MSF, CDC Foundation).', 'If you are not going to medical school, pursue the Clinical Research Coordinator path — it pays well and has genuine international demand from CROs like IQVIA, PPD, and Syneos Health. Get ACRP or SOCRA certification (can study online, exam fee approximately USD 400). IQVIA, Parexel, and Syneos Health all have regional offices in Asia and recruit Filipino CRCs for multinational trials. Public health master''s (MPH) abroad is another strong pivot — USAID, WHO, and CDC Foundation all hire Filipino MPH graduates.', 'SUMMARY'),
  ('note-SCI-011', 'Notes', 'BS Marine Biology', 'HONEST ASSESSMENT: BS Marine Biology is one of the most difficult degrees to convert to direct international employment. The pure research pathway almost universally requires a master''s or PhD. Internationally recognized Marine Biologist positions are very competitive globally — even PhD holders struggle to find permanent positions. The most realistic BS-level international paths are: (1) Dive industry — scientific diving instructor plus marine biology background equals employment at dive resorts, marine protected area management, or eco-tourism operators in Australia, Palau, Maldives, Indonesia, and Thailand. (2) Fisheries observer or fisheries management roles with international organizations (FAO, SEAFDEC, WCPFC). (3) Environmental consulting with marine component — EIA for offshore development. (4) Aquaculture technician roles internationally — growing sector with actual BS-level demand. The Philippines'' rich marine biodiversity gives Filipino marine biologists academic recognition, but converting this to employment abroad with just a BS is very challenging.', 'Get AAUS Scientific Diver certification and PADI Divemaster or Instructor rating — this combination gives you international dive industry employment options. Australia''s Great Barrier Reef Marine Park Authority and AIMS both hire field technicians with strong dive credentials. If you genuinely want to be a marine biologist internationally, plan for a master''s — fully funded scholarships at James Cook University (JCU, Australia''s top marine science school) and University of Auckland exist for Filipino students.', 'SUMMARY'),
  ('note-SCI-012', 'Notes', 'BS Marine Science', 'HONEST ASSESSMENT: BS Marine Science (broader than Marine Biology, includes physical oceanography, marine geology, and chemical oceanography) has similar international career challenges as Marine Biology. Research roles require master''s or PhD. BS-level international opportunities are niche: (1) Offshore oil and gas environmental monitoring — marine scientists are hired by EPC contractors for environmental baseline studies and monitoring during drilling and production. This is actually accessible with a BS plus diving plus GIS skills. (2) Offshore wind farm environmental assessment — rapidly growing sector in Europe (Netherlands, Germany, UK, Denmark). (3) Port and coastal engineering support — hydrographic surveying, sediment analysis. (4) Aquaculture industry internationally. The main difference from Marine Biology: Marine Science graduates with strong physical oceanography and GIS skills can enter offshore energy sector environmental roles more easily than pure marine biologists.', 'Specialize in physical oceanography or GIS and remote sensing — this opens offshore energy and coastal engineering consulting. Get certified in hydrographic surveying (FIG or IHO Category A or B) through online programs — this is a globally portable technical credential. DOST-PCAARRD and NAMRIA are worth joining early for domestic experience that supports later international opportunities.', 'SUMMARY'),
  ('note-SCI-013', 'Notes', 'BS Meteorology', 'HONEST ASSESSMENT: BS Meteorology has a narrow international career pathway. Domestic employers (PAGASA, DOST, CAAP) absorb most Filipino meteorology graduates. International career paths exist but are limited: (1) Aviation meteorology — ICAO requires certified meteorologists at international airports. Openings in Middle East, Southeast Asia, and Africa. Philippine meteorologists with ICAO certifications have been deployed to Qatar and UAE. (2) Offshore or oil and gas weather forecasting — oil platforms and LNG ships require dedicated meteorologists. This is one of the most accessible BS-level international roles. Companies like Offshore Weather Services, DTN, and StormGeo hire from developing countries. (3) Private commercial weather services — IBM The Weather Company, Maxar Technologies, private forecasting companies. These are increasingly remote-capable. (4) WMO or UNDP technical assistance — international organizations deploy meteorologists to developing countries for capacity building. (5) Academic or research roles require master''s or PhD. Note: PAGASA is severely understaffed and holds on to its meteorologists tightly. Government scholars may have service obligations.', 'Get ICAO aviation meteorologist certification — CAAP (Philippine) administers this. It is the most portable meteorology credential internationally. Offshore weather forecasting is a real and underappreciated niche — oil companies pay well for forecasters willing to work rotation schedules. DTN, Offshore Weather Services, and StormGeo all recruit from the Philippines. Learn Python for weather data analysis — NWP (Numerical Weather Prediction) modeling skills are increasingly required.', 'SUMMARY'),
  ('note-SCI-014', 'Notes', 'BS Molecular Biology and Biotechnology (MBB)', 'BS Molecular Biology and Biotechnology is one of the better positioned pure-science degrees for international employment because of two specific industry pipelines: (1) Ireland pharmaceutical and biotech manufacturing — Biologics production facilities (Amgen, Janssen, MSD, Regeneron, and Shire or Takeda all have large Irish biopharma plants) hire BS-level bioprocess technicians, QC analysts, and validation engineers directly. This is a genuine BS-level international pipeline. Ireland specifically hires Filipino biotechnology and science graduates for these roles via the Critical Skills Employment Permit. (2) Singapore Biopolis or biotech manufacturing — Lonza, Pfizer, and GSK all have significant manufacturing presence in Singapore hiring BS-level bioprocess and QC staff. (3) USA: Research associate or lab technician roles at biotech companies (not research scientist level — that is PhD). Production technician at pharmaceutical or biotech facilities. (4) Germany: Biotechnology technician in pharma production (Bayer, BASF, Merck KGaA) — requires B2 German for most positions. Graduate school: USA, UK, or Singapore master''s programs provide access to research scientist career track.', 'Target bioprocess technician and QC Analyst roles in Ireland — Amgen Dun Laoghaire, Janssen Biologics Cork, and MSD Carlow are all actively hiring BS-level biotech graduates internationally. The Critical Skills Employment Permit in Ireland has a clear PR pathway after 2 years. If you want to be a research scientist, plan for a master''s — look at NUS Singapore, Queen''s University Belfast, or UCL London for MBB-aligned master''s programs.', 'SUMMARY'),
  ('note-SCI-015', 'Notes', 'BS Volcano and Seismology Related Fields', 'HONEST ASSESSMENT: This is the most specialized and internationally restricted degree in this cluster. Global demand for volcanologists and seismologists is extremely limited — each country has only one or a handful of dedicated volcano or seismology agencies (USGS in USA, GNS Science in NZ, INGV in Italy, GSJ in Japan, GeoScience Australia), and competition for positions is fierce globally. PhD is the de facto requirement for any research position at these agencies. The few BS-level international paths are: (1) Geophysical field technician — seismic surveying for oil and gas exploration companies (SLB formerly Schlumberger, TGS, CGG Veritas). This is a real niche with deployment potential in Middle East, Africa, and Latin America. (2) Natural disaster risk consulting — multilateral organizations (World Bank, UNDP, UNDRR) employ disaster risk specialists; BS plus PHIVOLCS experience plus disaster risk certification is a viable pivot. (3) Earthquake engineering support roles for construction industry — adjacent to civil engineering seismic design. PHIVOLCS is understaffed and genuinely valued in ASEAN — some regional secondments exist under ASEAN SASOP (Standard Operating Procedure for Regional Standby Arrangements). The Philippines'' unique position as a highly active volcanic and seismic nation gives Filipino graduates specialized experience that is genuinely valued internationally, but the market is tiny.', 'Work at PHIVOLCS for 3-5 years first — this is your most valuable international asset. Publish if possible. Then apply for fully funded master''s programs at: University of Bristol (UK volcanic hazards), University of Auckland (geophysics), INGV (Italy — fully Italian government funded), or Tohoku University (Japan). UNDRR''s Sendai Framework implementation work needs disaster risk specialists — a pivot toward risk assessment and disaster risk reduction dramatically widens your international employment options.', 'SUMMARY'),
  ('note-SOC-001', 'Notes', 'BS Community Development', 'Community Development is overwhelmingly a domestic career in the Philippines. The international pathway exists but is highly competitive and indirect: (1) Work 3-5 years in PH with a credible INGO (CARE, Save the Children, World Vision PH office), build a strong portfolio of project results, then apply for international postings. (2) UN Volunteers (UNV) programme is the most accessible entry point — pays a living allowance (~$1,500-2,500/month), no salary, but counts as UN experience. (3) After UNV assignment, competitive for junior Professional Officer (JPO) or national officer roles within UN system. (4) Master''s degree (MSW, MPA, MPH, or M.Community Development) dramatically improves competitiveness for P-level UN posts. Starting salary abroad: INGO field staff $28,000-45,000; UN national professional officer $40,000-65,000; UN P-3 international staff $90,000+ (but very few slots). Honest assessment: most CD graduates work in LGU social welfare departments, DSWD, or local NGOs. International career is a 7-10 year project requiring master''s + INGO experience.', 'If international development work is your goal, treat your BS Community Development as the first step, not the destination. Plan for a master''s degree (MPA or MSW from a reputable school) and target the UN Volunteers programme for your first international posting. Build measurable project impact data from day one — INGOs and the UN want to see numbers (beneficiaries reached, funds managed, community outcomes).', 'SUMMARY'),
  ('note-SOC-002', 'Notes', 'BS Human Services / Guidance and Counseling', 'The primary international pathway for guidance counselors is school counseling at international schools in the Gulf and Asia. These schools (British, American, IB curriculum) actively recruit counselors who can support diverse international student bodies. Requirements typically include: bachelor''s degree in counseling/psychology/education, 2-3 years school counseling experience, English proficiency. The PRC Guidance Counselor license establishes professional credibility but is not directly recognized abroad — what matters is the degree, experience, and sometimes an international counseling credential (e.g., CACREP-accredited certificate program). Salary in UAE international schools: AED 8,000-14,000/month ($2,200-3,800/month, tax-free) = $26,400-45,600/year equivalent. Singapore international schools: SGD 48,000-70,000/year (~$36,000-52,000 USD). Qatar: QAR 12,000-18,000/month ($39,000-60,000/year). Housing and flights often included. Also growing: HR/employee assistance programme counselor roles at MNCs in Singapore and Hong Kong. Corporate wellness is a growing sector post-COVID.', 'Pass the PRC Guidance Counselor board exam and gain 2-3 years experience in a Philippine school — ideally one with international curriculum exposure or a private school with diverse student populations. Then target international school job boards (TES/Times Educational Supplement, SearchAssociates, ISS staffing). A short CACREP-aligned certificate course online will strengthen your application. The Gulf has the largest number of openings and is the fastest deployment.', 'SUMMARY'),
  ('note-SOC-003', 'Notes', 'BS Indigenous Peoples Studies', 'BS Indigenous Peoples Studies is the most domestically-focused degree in this cluster. The degree is essentially unique to the Philippines in this exact form — it is specifically designed for NCIP, IPRA (Indigenous Peoples Rights Act) compliance work, ancestral domain management, and IP community development in the Philippine context. International career is extremely limited and indirect. The countries where Indigenous Studies expertise translates internationally are Canada (First Nations/Metis/Inuit policy), New Zealand (Maori rights, Treaty of Waitangi), and Australia (Aboriginal affairs), but these countries have their own programs training their own graduates and rarely recruit internationally. Realistic international pathways: (1) UN Permanent Forum on Indigenous Issues (UNPFII) — intern/NGO participation track, usually voluntary or stipend-only; (2) INGO work in Indigenous advocacy (Survival International, Forest Peoples Programme) — typically UK/Europe-based organizations, require strong advocacy/communications skills; (3) Academic route — PhD in anthropology, indigenous studies, or related field at a Canadian or NZ university, which opens academic and policy positions. Honest assessment: 95% of career opportunities are in the Philippines. This degree is a genuine vocation for those committed to serving IP communities in PH.', 'If you are passionate about indigenous rights and want international exposure, plan for a PhD or master''s at a university with a strong Indigenous Studies program (University of British Columbia, University of Auckland, Australian National University). Alternatively, develop expertise in international indigenous rights frameworks (UNDRIP, ILO Convention 169) and position yourself as a policy specialist for Philippine government negotiations with UN bodies.', 'SUMMARY'),
  ('note-SOC-004', 'Notes', 'BS Peace Studies', 'BS Peace Studies is primarily designed for the Philippine context — specifically peacebuilding in Mindanao (Bangsamoro process, MILF/MNLF peace agreements) and community conflict resolution. The international career pathway in conflict resolution and peacebuilding is highly competitive and almost always requires a master''s degree. Realistic international pathways: (1) UN Department of Peace Operations (DPO) or political affairs officer roles — require P-2 entry via competitive YPP (Young Professionals Programme) exam or JPO sponsorship, plus master''s and multiple languages. (2) ICRC (International Committee of the Red Cross) — one of few organizations that will hire bachelor''s-level field staff for logistician/protection assistant roles; requires mobility (willingness to go to conflict zones) and competency in a second language. (3) Mindanao-focused work is internationally recognized — graduates who document peace process work with GPH-MILF, Bangsamoro Autonomous Region work, or Lumad protection can position themselves as Philippine peacebuilding specialists for international academic or policy conferences. (4) OCHA internships provide UN experience; UNIDIR (disarmament research) has internship programs. Honest assessment: Most Peace Studies graduates work in Mindanao NGOs, OPAPP, ARMM/BARMM, or LGU community conflict resolution. International career requires 7-10 years of specialized experience + master''s degree.', 'If Geneva, Brussels, or New York is the goal, a master''s degree is non-negotiable — apply to the Graduate Institute Geneva, Uppsala University (top peace research program), Notre Dame Kroc Institute, or George Mason''s Carter School for Peace and Conflict Resolution. Your Philippine Mindanao experience is genuinely valuable internationally — it is a complex, live peace process. Document it rigorously and present it as a case study, not just a job history.', 'SUMMARY'),
  ('note-SOC-005', 'Notes', 'BS Psychology', 'Psychology has growing global demand due to the post-COVID mental health crisis. However, the pathway varies significantly by specialization and destination. KEY CHALLENGE: Most countries reserve the title ''Psychologist'' for doctoral-level practitioners. A BS Psychology + PRC license from PH is typically treated as an ''assistant psychologist'' or ''psychometric tester'' level internationally, NOT as a licensed clinical psychologist. CRITICAL DISTINCTION: (A) CLINICAL PSYCHOLOGY path — requires master''s/doctoral-level training (D.Psych UK, PsyD/PhD USA, master''s clinical AU) after the BS degree. Philippine BS + PRC license alone will NOT get HCPC or AHPRA clinical registration. (B) I/O PSYCHOLOGY path — Industrial-Organizational psychology in corporate HR, assessment centers, talent management is MORE internationally accessible at bachelor''s level + relevant experience, especially in Singapore, UAE, and HK. (C) PSYCHOMETRICS / ASSESSMENT path — psychometric assessment roles in schools, clinics, corporates are accessible with PRC license + experience. UK: HCPC regulates clinical, counselling, and forensic psychologists — requires postgraduate training. AU: AHPRA requires a minimum of 6 years training (4-year degree + 2-year master''s, or internship sequence). USA: ''psychologist'' requires doctoral degree in most states. MOST VIABLE INTERNATIONAL PATHWAY: (1) Pass PRC Psychologist exam. (2) Work 2-3 years in PH (HR/assessment, EAP, school psychology). (3) Apply to UK master''s in Applied Psychology or AU master''s in Professional Psychology. (4) Upon completion, register with HCPC/AHPRA and enter clinical workforce.', 'The PRC license is a great credential for the Philippines, but internationally it gets you ''assistant psychologist'' level at best. If you want to be a full psychologist internationally, plan for a master''s degree. The most internationally-portable short-term path: go into I/O psychology (HR, talent assessment, organizational behavior) in Singapore or Hong Kong MNCs, where a BS + experience is valued without clinical registration requirements. Alternatively, the UAE and Gulf have demand for school psychologists and HR assessment specialists at bachelor''s level.', 'SUMMARY'),
  ('note-SOC-006', 'Notes', 'BS Social Work', 'Social Work is one of the BEST international career options among social sciences courses. The UK is actively recruiting Filipino social workers to address a severe shortage in local authority children''s services, adult social care, and mental health social work. Key facts: (1) The Philippines is a recognized source country for UK social work — Social Work England accepts applications from internationally qualified social workers. (2) PRC Licensed Social Worker is the required base credential — you must have this before applying internationally. (3) UK process: Submit qualifications to Social Work England for international registration review; approximately 3-6 months processing; pass English language test; complete a period of supervised practice (adaptation period, typically 3-6 months). (4) Australia AASW: The Philippine social work qualification is generally assessed as meeting AASW membership requirements — this is well-established. Australia has significant shortages in child protection and NDIS disability support social work. (5) Canada: Provincial colleges (BCCSW, OCSWSSW etc.) assess international qualifications; varies by province; Ontario and BC most active recruitment. (6) New Zealand has a Social Workers Registration Board (SWRB) — international route available. (7) Ireland has Social Workers Registration Board Ireland (CORU) — also actively recruiting. SALARY: UK starting —28,000-35,000/year; senior practitioners —40,000-55,000. Australia AUD 65,000-95,000/year. Canada CAD 52,000-75,000. All significantly above Philippine rates.', 'Pass the PRC Social Worker licensure exam immediately — this is your ticket internationally. The UK is the fastest deployment with a well-established route for Filipino social workers. Gain 2 years of post-licensure experience in child welfare, elder care, or mental health social work in the Philippines. Then apply to UK local authorities — Manchester, Leeds, Birmingham, and London boroughs actively post internationally. UK will often fund your adaptation period. The Health and Care Worker visa is available specifically for social workers. Ireland is an underrated option — similar language, EU access, very strong social work demand.', 'SUMMARY'),
  ('note-OTH-001', 'Notes', 'AB/BS Political Science', 'AB/BS Political Science is fundamentally a generalist academic degree. Its primary career outcomes in the Philippines are: government (DFA, DILG, DBM, Congress staff), law school, journalism, or academe. International careers exist but are structurally difficult because: (1) There is no PRC board exam, so there is no internationally recognized credential signal; (2) ''Political scientist'' is rarely a job title outside academia; (3) Employers look for functional skills (policy analysis, research, communications) that polisci teaches but are not exclusive to it. VIABLE INTERNATIONAL PATHWAYS: (A) UN/Multilateral — DFA diplomatic service is domestic, but UN careers in political affairs (DPPA, DPO) require competitive YPP exams, language skills, and a master''s degree. ADB, World Bank, ASEAN Secretariat recruit policy analysts with polisci/IR/economics backgrounds but typically require master''s + quantitative skills. (B) Political Risk Analysis — this is a growing sector. Firms like Control Risks, FTI Consulting, Oxford Analytica, and Verisk Maplecroft hire analysts with regional expertise. Being Filipino and fluent in Southeast Asian political dynamics is a genuine comparative advantage. Starting analyst roles in London/Singapore/New York: $40,000-65,000/year. (C) International Journalism — polisci graduates who develop strong writing skills can pursue journalism with international wire services (Reuters, AFP, Bloomberg, AP) as local correspondents/stringer, or go abroad for graduate study in journalism. (D) Graduate school abroad — the most common international pathway, not a direct career but an enabler.', 'Political Science is a gateway degree, not a destination career. The most internationally deployable combination: polisci degree + master''s in public policy (or IR, or journalism) + a specific regional expertise (Southeast Asia, East Asia, South China Sea) + one additional language. For the UN track, target the Young Professionals Programme or Junior Professional Officer program with DFA sponsorship. For the private sector, political risk consulting firms in Singapore or London value ASEAN expertise deeply — your Philippines knowledge is genuinely rare to them.', 'SUMMARY'),
  ('note-OTH-002', 'Notes', 'AB Communication / Mass Communication / Journalism', 'Communication/journalism graduates have one of the more diverse international career landscapes among social science graduates because skills are portable. Key pathways: (1) INTERNATIONAL JOURNALISM: Filipino journalists have worked at Reuters (Manila bureau and international postings), AFP, AP, Bloomberg, CNN Philippines affiliates. Wire service stringer/contributor work begins locally but international postings are competitive. Al Jazeera English in Doha actively diversifies its newsroom. BBC World Service Southeast Asia bureau covers Philippines. For broadcast, CNN (Atlanta or international bureaus) requires strong on-camera reel + digital skills. Starting international journalism salary: $28,000-45,000 at wire agencies; senior international correspondent: $70,000-100,000. (2) PR / COMMUNICATIONS IN MNC HUB CITIES: Singapore, Hong Kong, Dubai, and Kuala Lumpur are regional hubs for multinational PR agencies (Edelman, Ogilvy PR, Weber Shandwick, FleishmanHillard, Burson Marsteller). Filipino communications professionals are valued for English fluency, ASEAN market knowledge, and strong work ethic. Agency roles: $30,000-60,000 (SGD/HKD/AED equivalents). In-house comms at MNCs: $40,000-80,000. (3) CONTENT MARKETING / DIGITAL (REMOTE): The fastest-growing international pathway. Filipino content marketers, copywriters, SEO specialists, and social media managers now command $25,000-60,000/year working remotely for US, UK, and Australian clients. Platforms: Upwork, Toptal, LinkedIn. Key skills: SEO writing, content strategy, HubSpot/Salesforce marketing, social media analytics. (4) SOCIAL MEDIA / INFLUENCER MANAGEMENT: Digital agencies in Singapore, Dubai, and Bangkok hire Filipino social media strategists. (5) BROADCAST MEDIA in Gulf: Abu Dhabi Media, Qatar Al Jazeera, Saudi MBC have Filipino on-air talent (particularly in technical/production roles and for Filipino community programming).', 'Build a portfolio from day one — published articles, PR campaigns you''ve run, content you''ve produced, analytics results. No employer abroad cares about your GPA; they care about your work. The fastest international pathway is remote content/digital marketing — build skills in SEO (take Google''s free courses), content strategy, and social media analytics. Within 2 years you can be earning $30,000-50,000/year remotely from the Philippines before even moving. For journalism: file clips with national newspapers, wire services, and international outlets covering Philippine stories — this is your portfolio.', 'SUMMARY'),
  ('note-OTH-009', 'Notes', 'Juris Doctor (JD) / Law', 'Critical reality: passing the Philippine Bar gives you the right to practice Philippine law — this does NOT entitle you to practice law in any other country. Every jurisdiction has its own bar/solicitor qualification. However, significant international law careers ARE available to Philippine-licensed lawyers via specific pathways: (1) LLM + FOREIGN BAR: An LLM from a reputable foreign law school, followed by the relevant bar exam, opens full international practice. Most strategic: New York State Bar (can be taken by foreign law graduates with an LLM from a NY-approved school — allows practice of US and NY law); New York has the most globally recognized US bar for international work. England/Wales: the SQE (Solicitors Qualifying Examination) replaced the old route in 2021; foreign lawyers with an LLM can take SQE and qualify as a solicitor. (2) INTERNATIONAL ARBITRATION: The most accessible international law career without a foreign bar. International arbitration (ICSID, ICC, SIAC, HKIAC, UNCITRAL) employs lawyers from any jurisdiction. Philippine lawyers with expertise in investment law, trade law, energy law, or construction can build international arbitration careers. Many operate as counsel or arbitrator for cross-border disputes involving Philippines. SIAC (Singapore International Arbitration Centre) and HKIAC are key Asia-Pacific hubs. (3) IN-HOUSE COUNSEL AT MNCs IN PH: MNCs (Procter & Gamble, Unilever, HSBC, Citibank, Accenture) operating in the Philippines need lawyers who understand Philippine law — these roles are domestic but internationally-connected, offering exposure to global legal work, higher pay ($40,000-80,000/year at senior levels), and pathways to international transfers within the MNC. (4) ADB / World Bank / ASEAN LEGAL ROLES: Asian Development Bank''s Office of the General Counsel employs Filipino lawyers. World Bank likewise. ASEAN Secretariat has a legal affairs department. These positions typically require an LLM and several years of litigation/transactional experience. (5) ACADEMIC ROUTE: Philippine law professors who publish in international journals and attend international academic conferences build a global academic law profile. (6) MIGRATION TO CANADA: Canada''s paralegal and legal consultant streams are accessible without full Canadian law qualification; Ontario specifically licenses paralegals. This is not full lawyer practice but an entry point.', 'Pass the Philippine Bar — this is foundational. Then identify which international law track you want: (A) US track — work 2-3 years at a top Philippine law firm or corporate in-house, then apply for an LLM at NYU, Columbia, Georgetown, Michigan, or Fordham (all ABA-approved for NY Bar eligibility), take and pass the New York Bar, then apply at international law firms with NY offices or Philippines desks. (B) Singapore/Arbitration track — take the LLM at NUS or SMU Singapore (costs SGD 40,000-50,000; strong scholarship options), focus on international arbitration coursework, intern at SIAC, build an arbitration career. (C) UK/Global track — LLM at LSE, Oxford, Cambridge, then take the SQE to qualify as a solicitor. Most expensive but opens Magic Circle and global law firm doors. The NYC Bar route is the most financially rewarding long-term with US BigLaw starting salaries at $200,000+.', 'SUMMARY'),
  ('note-OTH-010', 'Notes', 'AB/BS Foreign Service / International Relations', 'Foreign Service/International Relations is primarily oriented toward Philippine government service (DFA diplomatic career) and post-graduate academic pursuits. While the degree teaches international affairs, the actual career track for international multilateral work is highly competitive and structurally requires: (1) master''s degree, (2) second language, and often (3) prior DFA or INGO experience. VIABLE INTERNATIONAL PATHWAYS: (A) DFA FSOE — the most direct. Pass the DFA Foreign Service Officer Examination (competitive 5-stage exam). As a Foreign Service Officer, you are deployed to Philippine Embassies, Consulates, and Permanent Missions abroad. This IS an internationally-deployed career — in Washington DC, Geneva, New York (UN), Tokyo, Beijing, Riyadh, Dubai, etc. — but it is a Philippine government career, not a foreign employer career. (B) UN/MULTILATERAL — UN Young Professionals Programme (YPP) is the most competitive international career track; requires master''s and passing a competitive written examination plus interview. ADB Young Professionals Program (YPP): highly selective (~30 spots/year globally); requires graduate degree + strong analytical skills; pays $70,000-90,000 starting; based in Manila but involves international travel and multi-country assignments. World Bank YPP: similarly selective; preference for economics/development focus. ASEAN Secretariat: hires professional staff (communications, policy, legal) from member states including Philippines; based in Jakarta; competitive. (C) BILATERAL EMBASSY LOCAL STAFF: Foreign embassies in Manila (US Embassy, Australian Embassy, British Embassy, Japanese Embassy) hire local Filipinos in political, communications, trade, and visa sections — these are ''locally employed staff'' positions, not diplomatic careers, but provide international exposure and competitive salaries. (D) INTERNATIONAL DEVELOPMENT ORGANIZATIONS: ADB (Manila-based), UNDP PH office, ILO PH office, World Bank PH office are all Manila-based international organizations employing hundreds of Filipinos in program analyst, research, communications, and project management roles.', 'The DFA career is the most direct international deployment for this degree — study well for the FSOE (5 stages: written exam, essay, case study, committee exercise, psychological assessment). If the UN or multilateral track is your goal, a master''s in public administration, international relations, or economics is non-negotiable. Apply early to the ADB Young Professionals Program (closes in January each year, based in Manila) — it''s one of the best starting salaries and career tracks in Asia for development work. Learning French adds immense value for UN careers specifically.', 'SUMMARY'),
  ('note-TEA-001', 'Notes', 'BS Culture and Arts Education', 'Culture and Arts Education has a niche but real international pathway through international and IB schools, which actively recruit specialist arts teachers. The IB (International Baccalaureate) Diploma Programme includes Visual Arts, Music, and Theatre as standalone subjects — creating demand for specialist Arts educators at 5,000+ IB schools worldwide. The UAE has 600+ international schools with active arts programs. Domestic demand remains strongest due to the DepEd MAPEH program. Graduates can also pivot into arts administration, cultural tourism, museum education, and creative industries management. The British Council''s global arts education programs sometimes recruit Filipino arts educators for project-based work. Career ceiling internationally is moderate — arts teachers are in less acute shortage than STEM or SPED teachers, so strong portfolio and IB PYP/MYP/DP training certification are differentiators.', 'Get your LET first, then build a strong digital portfolio of student work and your own creative output. Pursue IB Category 1 workshop training (available online via IBO). The UAE and Qatar international school market actively recruit arts specialists — GEMS Education, Taaleem, and Aldar Academies are top hirers. Salary in UAE is tax-free.', 'SUMMARY'),
  ('note-TEA-002', 'Notes', 'BS Early Childhood Education (ECE)', 'ECE is one of the strongest OFW teacher pathways. The Gulf states have massive demand for qualified kindergarten and nursery teachers for expat community international schools. UAE alone has 200,000+ school-age expat children requiring EYFS-based or play-based early education. Filipino ECE teachers are specifically sought for their warmth, English proficiency, and patience. The UK EYFS (Early Years Foundation Stage) framework is the gold standard internationally — many international schools in Asia and the Middle East follow it. Filipino ECE graduates can get UK QTS recognition through the iQTS route or work as Early Years Practitioners without full QTS in UK nurseries. Australia''s ACECQA (Australian Children''s Education & Care Quality Authority) process recognizes PH ECE degrees with some bridging requirements. Key advantage: ECE demand grows with expatriate population growth in Gulf — this is a steady and growing market for Filipinos.', 'Pass your LET as early as possible. Then take a UK EYFS online course (many available from UK providers like Highfield or CACHE) to show familiarity with the international standard. Filipino teachers in UAE Kindergartens regularly earn AED 6,000-10,000/month ($1,600-2,700) tax-free — far more than DepEd salaries. Apply through Teach Away, Search Associates, or directly to GEMS and Taaleem school groups.', 'SUMMARY'),
  ('note-TEA-004', 'Notes', 'BS Special Needs Education (SPED)', 'SPED teachers are among the most globally in-demand educators. In the USA, the Individuals with Disabilities Education Act (IDEA) mandates free appropriate public education for all children with disabilities — creating a structural, law-mandated shortage that cannot be filled domestically. The US Bureau of Labor Statistics consistently ranks Special Education as one of the most understaffed teaching fields, with 50,000+ unfilled positions annually. UK SEND (Special Educational Needs and Disability) teachers are on the official shortage occupation list, meaning faster visa processing. Australia''s NDIS (National Disability Insurance Scheme) created enormous demand for support workers and special education teachers. Canada''s inclusive education mandate across all provinces has the same structural driver as the US. Filipino SPED teachers are particularly competitive because Philippine SPED programs train graduates in autism spectrum disorder, intellectual disability, visual impairment, hearing impairment, and learning disabilities — comprehensive training that matches international needs.', 'This is arguably the single best international teaching pathway from the Philippines. Apply to US school districts through Teach Away or US-based recruitment agencies. Many US public school districts in high-shortage states (Texas, Florida, California, Arizona) will sponsor your H-1B or J-1 visa. In the UK, SEND is on the Shortage Occupation List — faster visa and sometimes lower salary threshold. Australia has direct pathways through AITSL. Get experience with autism and multiple disabilities during your degree — these are the highest-demand specializations.', 'SUMMARY'),
  ('note-TEA-005', 'Notes', 'BS Sports and Exercise Science', 'Sports and Exercise Science has highly diverse career tracks with very different international profiles. Three main pathways: (1) PE Teacher in international schools — Gulf states, Singapore, Hong Kong, UK all hire PE specialists, this is the most accessible international pathway; (2) Strength & Conditioning Coach / Sports Performance — professional sports teams, elite academies, national sports programs; (3) Exercise Science / Fitness Industry — commercial gyms, corporate wellness, rehabilitation support. The PE teacher pathway is most accessible early-career. The professional sports pathway is very competitive but Philippines graduates have placed in Gulf football academies and Asian sports institutes. Notably: no PRC board exam for Sports Science itself — this means international certifications (NSCA, ACSM, ACE) are the de facto credentials. NSCA CSCS is the gold standard for S&C roles globally. Gulf fitness market (UAE, Saudi Arabia, Qatar) has boomed post-COVID with massive gym expansions.', 'Do NOT wait for a PRC board that doesn''t exist. Instead, invest in internationally recognized certifications: NSCA-CSCS ($435 exam fee) or ACSM-EP are global door-openers. For PE teaching internationally, if you took the LET track, that helps. In the UAE gym market, even an ACE Personal Trainer cert gets you jobs at Fitness First, GymNation, or Pure Gym. Professional sports is extremely competitive — start with academy coaching or school-based PE, build your portfolio, then move up.', 'SUMMARY'),
  ('note-OTH-015', 'Notes', 'AB/BS Elementary Education (BEED)', 'Elementary/Primary teaching (BEED) has excellent international demand — arguably more stable than secondary because every child starts at primary level regardless of economic conditions. The UK, Australia, New Zealand, and Canada all have declared shortages of primary school teachers. New Zealand is particularly significant: primary teachers are on the NZ Green List (Straight to Residence pathway) meaning BEED holders can apply for permanent residence directly — this is a major immigration advantage unique to this profession. The previous research note focused on Secondary (BSED); the BEED pathway to primary/elementary teaching internationally is equally strong and in some countries stronger. UAE is the fastest entry point — no complex credentialing required to start. UK via iQTS or overseas trained teacher route offers the best long-term career and immigration outcome in Europe.', 'Your single biggest advantage over BSED graduates is New Zealand''s Green List — primary teachers can apply for permanent residence directly without first getting a work visa. This is extremely rare in immigration. For UK: apply through Teach Away or directly to MAT (Multi-Academy Trust) groups that sponsor Skilled Worker visas. UAE is your fastest start — many BEED holders are in UAE within 5-8 months of graduating and passing LET.', 'SUMMARY'),
  ('aiimpact-IT-001', 'AI Impact', 'Computer Science', 'CS is not dying — it is the most in-demand field because of AI. The job changes from writing all the code yourself to directing AI that writes code and solving the problems AI cannot solve. Learn Python, AI/ML basics, and systems design now.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-IT-004', 'AI Impact', 'Information Technology', 'General IT support jobs face real automation pressure — AI chatbots already handle tier-1 helpdesk. Specialize in cybersecurity, cloud, or business analysis where AI needs humans to supervise it.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-ENG-007', 'AI Impact', 'Computer Engineering', 'Computer Engineering may be the best-positioned degree in the AI era. NVIDIA, Apple, Google, and Meta are all building custom chips. If you combine hardware and AI knowledge, you are nearly irreplaceable.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-ENG-009', 'AI Impact', 'Electronics & Communications Engineering', 'ECE is a safe and growing career. AI is a tool in your hands — it helps you design better antennas, manage networks faster, and optimize signals automatically. The real work in new frequency bands, defense systems, and satellite comms still needs you.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-ENG-008', 'AI Impact', 'Electrical Engineering', 'EE is one of the safest engineering careers in the AI era. The energy transition to solar, wind, and EVs is creating more EE jobs than AI can eliminate. Add renewable energy and smart grid skills and your career is extremely secure.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-ENG-017', 'AI Impact', 'Mechanical Engineering', 'ME is transforming, not disappearing. AI now helps you design faster by generating thousands of options automatically. But you still decide which design is safe, manufacturable, and right for the customer. Add robotics and digital twin skills to your toolkit.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-006', 'AI Impact', 'Civil Engineering', 'Civil Engineering is safe and growing in the Philippines. AI takes over the calculations — you do the judgment calls about safety, community impact, and disaster resilience. Learn BIM and drone survey skills and you will be ahead of the curve.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-005', 'AI Impact', 'Chemical Engineering', 'Chemical Engineering is transforming into AI-augmented research. AI runs simulations and discovers materials faster — you decide what to build, how to scale it safely, and how to meet environmental standards. Add sustainability and battery materials to your focus.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-013', 'AI Impact', 'Industrial Engineering', 'IE might be the degree most needed right now. Every company deploying AI needs Industrial Engineers to redesign how humans and machines work together. You are the translator between the AI and the organization — that job is growing, not shrinking.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-012', 'AI Impact', 'Geodetic Engineering', 'Geodetic Engineering is evolving from survey fieldwork to AI-powered insight generation. The satellite data, the LiDAR, the drones — all those produce massive datasets that GEs interpret. Add GIS scripting and drone photogrammetry and your career scope triples.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-020', 'AI Impact', 'Metallurgical Engineering', 'Metallurgical Engineering is more valuable than ever because of the EV revolution. Every electric car needs battery materials — nickel, cobalt, lithium — that MetE graduates know how to process. The Philippines'' mineral wealth makes this especially relevant for you.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-024', 'AI Impact', 'Sanitary Engineering', 'Sanitary Engineering is extremely secure — clean water is a fundamental human need that AI cannot deliver without you. AI helps you monitor water quality in real time and optimize treatment plants, but the infrastructure design, community work, and regulatory compliance are yours.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-001', 'AI Impact', 'Agricultural Engineering', 'Agricultural Engineering is one of the most important careers for the Philippines future. AI tools let you monitor crops by drone, automate irrigation, and predict yields from satellite data — but you design the systems, train the farmers, and adapt the technology to Philippine conditions.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-008', 'AI Impact', 'Medicine', 'Medicine is one of the safest careers in the AI era. AI helps you read X-rays faster and catch diagnoses you might miss — but you are still the one who examines the patient, explains the diagnosis, makes the ethical call, and signs the prescription. AI makes you a better doctor, not a jobless one.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-HLT-005', 'AI Impact', 'Nursing', 'Nursing is one of the safest careers you can choose. AI takes over the paperwork and monitoring alerts so you can focus on patients. The global demand for nurses is only growing — the US and EU have critical shortages they cannot fill. Your skills will be needed everywhere.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-HLT-003', 'AI Impact', 'Medical Technology', 'Medical Technology is transforming, not disappearing. AI runs the routine tests automatically — you verify the unusual results, troubleshoot the instrument errors, and make judgment calls on complex specimens. Add LIS and molecular diagnostics skills.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-HLT-009', 'AI Impact', 'Physical Therapy', 'Physical Therapy is one of the safest careers you can choose. The hands-on healing you provide — the joint mobilizations, the rehabilitation exercises, the therapeutic relationship — cannot be replicated by any machine. AI helps you track progress and reduce paperwork. Your career is secure.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-HLT-007', 'AI Impact', 'Occupational Therapy', 'Occupational Therapy has one of the lowest AI automation risks of any profession — 0.4% according to Oxford research. You work with people recovering function and learning to live with disabilities. No AI can sit with a patient and guide them through those deeply human moments.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-HLT-001', 'AI Impact', 'Dentistry', 'Dentistry is one of the most AI-proof careers available. The procedures you perform — fillings, extractions, root canals, implants — require your hands, your training, and your judgment. AI helps you catch what you might miss on an X-ray. Your career is safe and the demand in the Philippines is enormous.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-HLT-008', 'AI Impact', 'Pharmacy', 'Pharmacy is transforming — the robot can count the pills, but it cannot counsel your patient on how to take five medications without side effects or flag the dangerous interaction the doctor missed. Shift your focus toward clinical pharmacy and pharmacogenomics for a strong future.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-HLT-006', 'AI Impact', 'Nutrition and Dietetics', 'Your career as a nutritionist is safe in the areas that matter most — clinical nutrition for sick patients, community health programs, and the complex behavioral work of helping people change their eating habits. AI apps can give general advice but they cannot replace your clinical judgment.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-014', 'AI Impact', 'Veterinary Medicine', 'Veterinary Medicine has one of the lowest AI automation risks — only 7%. You operate, examine, diagnose, and comfort both animals and their owners in ways no machine can replicate. The demand for vets is growing globally and locally, driven by the pet industry boom and food security needs.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-ENG-011', 'AI Impact', 'Food Technology', 'Food Technology is changing but not disappearing. AI will automate the inspection and sorting on the factory floor, but who designs the new snack that captures Filipino taste preferences? Who navigates the FDA/BFAD approval process? Who handles the food recall crisis? That is still you.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-BUS-001', 'AI Impact', 'Accountancy', 'Accountancy is honest: entry-level accounting tasks are being automated fast. The bookkeeping, the data entry, the routine audit sampling — AI does it better. But the licensed CPA who advises on complex tax strategy, forensic accounting, and financial decisions is more valuable than ever. You need to aim for that advisory role from day one.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-OTH-006', 'AI Impact', 'Business Administration', 'Business Administration is safe if you specialize. Generic BA graduates doing administrative work face automation pressure. But the business leader who can navigate AI tools, lead digital transformation, and build client relationships — that person is more valuable than ever. Pick a specialization and add AI fluency.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-004', 'AI Impact', 'Economics', 'Economics is transforming rather than declining. AI runs the standard regressions and compiles the data faster than you — but the economist who can design the right question, choose the right model, interpret structural breaks, and advise policymakers is irreplaceable. Add Python, causal inference, and policy specialization.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-009', 'AI Impact', 'Law', 'Law is transforming, not dying. AI now reviews thousands of documents and drafts contracts automatically — but the lawyer who can walk into a courtroom, advise a client facing crisis, and navigate complex regulations is irreplaceable. Learn the AI tools early, specialize in high-value practice areas, and you will command premium rates.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-003', 'AI Impact', 'Criminology', 'Criminology is safe in its core — law enforcement, investigations, and corrections require human judgment and accountability that AI cannot replace. But the data analysis side is growing fast. Criminologists who add digital forensics and AI crime analysis tools to their skillset are highly employable in PNP, NBI, and cybercrime units.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-SOC-005', 'AI Impact', 'Psychology', 'Psychology is one of the safest careers you can choose. The therapeutic relationship — the trust, the empathy, the clinical judgment built over years of training — is exactly what AI cannot replicate. The Philippines has a severe shortage of mental health professionals. Your career prospects are excellent and your work matters deeply.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-SOC-002', 'AI Impact', 'Guidance and Counseling', 'Guidance Counseling is one of the most secure careers available. DepEd mandates a counselor in every school but most schools do not have one — meaning demand far exceeds supply. The crisis intervention, the abuse disclosures, the college counseling conversations — these require a human being, not an app.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-SOC-006', 'AI Impact', 'Social Work', 'Social Work is a secure career because it is fundamentally about human relationships and community advocacy — things AI cannot do. The Philippines has a massive unmet need for social workers in government, NGOs, and communities. AI will help you with the paperwork so you can focus on the families who need you.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-IT-005', 'AI Impact', 'Library and Information Science', 'Library Science is transforming into information science. The person who can navigate, curate, and critically evaluate information in an ocean of AI-generated content is more valuable than ever — not less. The AI Librarian is becoming a real job. Add digital preservation, research data management, and AI literacy instruction to your toolkit.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-TEA-003', 'AI Impact', 'Education', 'Teaching is one of the safest careers in the Philippines. DepEd is the largest employer in the country and demand far exceeds supply. AI can generate worksheets and grade multiple choice tests, but the teacher who shows up for a student who is struggling at home — who motivates, mentors, and values-forms — that is irreplaceable.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-ARCH-001', 'AI Impact', 'Architecture', 'Architecture is transforming with AI tools handling the repetitive drafting and basic design variations. But you still design the building that fits the culture, survives the typhoon, and meets the LGU requirements. Learn BIM, generative design tools, and sustainable design — and your career is strong.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-SCI-005', 'AI Impact', 'Biology / Life Sciences', 'Biology is a growing field, not a shrinking one. AI tools like AlphaFold are transforming research speed — but the fieldwork in Philippine coral reefs, the experimental design, and the scientific judgment still need you. Add bioinformatics to your training and you bridge biology with the most in-demand tech skills.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-SCI-007', 'AI Impact', 'Chemistry', 'Chemistry is transforming with AI doing the routine spectra analysis and reaction predictions. But you still design novel experiments, handle hazardous materials safely, navigate Philippine BFAD regulations, and develop natural products chemistry that draws on our unique biodiversity.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-SCI-002', 'AI Impact', 'Physics', 'Physics is one of the safest and most future-proof degrees you can take. AI runs on mathematics and physics — the people who deeply understand both will be the ones building and auditing the AI systems that run the world. A physics degree opens doors to data science, AI research, quantum computing, and space technology.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-SCI-001', 'AI Impact', 'Mathematics and Statistics', 'Math and Statistics graduates are well-positioned in the AI era because AI runs on mathematics. The question shifts from doing the calculation to knowing which calculation to run, validating the model assumptions, and communicating results to decision-makers. Add Python and data science skills and you are among the most employable graduates in the country.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-SCI-009', 'AI Impact', 'Geology', 'Geology is essential for the Philippines given our place on the Ring of Fire. Your fieldwork — mapping hazards, assessing mining sites, responding to volcanic activity — cannot be replaced by AI. The technology makes you faster and more accurate. Add GIS and remote sensing skills and your career in MGB, PHIVOLCS, or mining becomes extremely strong.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-013', 'AI Impact', 'Agriculture', 'Agriculture is one of the safest careers you can choose because feeding people is non-negotiable and the Philippines cannot afford to get it wrong. AI helps with crop monitoring and precision irrigation — but the extension work, the farmer training, the adaptation to Philippine conditions — those need you. WEF says this is the #1 job growth category by 2030.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-OTH-011', 'AI Impact', 'Fisheries Technology', 'Fisheries Technology has strong job security because the Philippines depends on fisheries for food security and the livelihoods of millions of coastal Filipinos. AI is making monitoring and management better — and that requires trained fisheries professionals to operate and interpret the technology. Your local knowledge of Philippine waters and communities is your advantage.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-MAR-001', 'AI Impact', 'Marine Transportation', 'Marine Transportation is a strong career for the Philippines — we supply 1 in 4 of the world''s seafarers. AI is handling navigation assistance and predictive maintenance, but your STCW certification, seamanship, and human judgment in emergencies remain essential. Add e-navigation and cyber security training for the autonomous ship era.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-ENG-003', 'AI Impact', 'Aviation', 'Aviation is a safe and growing career. The FAA and CAAP require licensed human pilots on every commercial flight — that is not changing anytime soon. AI makes flying safer by handling routine tasks, but your judgment in emergencies and your certification remain legally required. The growing Philippine aviation sector means strong local demand.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-BUS-003', 'AI Impact', 'Tourism and Hospitality Management', 'Tourism and Hospitality careers are safe at the high end and under pressure at the low end. AI will handle booking chatbots and automated check-ins — but the experience designer who crafts a Palawan eco-tour, the event planner who runs a 500-person conference, and the front-office manager who diffuses a guest crisis — those roles need you.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-OTH-002', 'AI Impact', 'Mass Communication and Journalism', 'Mass Communication and Journalism are honestly at risk for commodity content work — AI already writes financial news and sports scores. But investigative journalism, accountability reporting, and documentary storytelling are irreplaceable. The Philippines has one of the world''s most active misinformation environments — human journalists who can verify facts and hold power accountable are more important than ever.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-ARCH-003', 'AI Impact', 'Fine Arts and Multimedia Arts', 'Fine Arts and Multimedia Arts face the most honest disruption of any creative field. AI can already generate images, videos, and ad copy in seconds. The question is: can you do what AI cannot — build the brand strategy, understand the Filipino market, direct the creative vision, and protect your client''s identity from generic AI output? Master the AI tools and position yourself as the creative director, not the executor.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-OTH-001', 'AI Impact', 'Political Science', 'Political Science is transforming into one of the most relevant degrees for the AI era — not because you build AI, but because you govern it. Every government agency needs people who can write AI policy, analyze political data, and advocate for ethical technology. The politicians and diplomats who understand AI will shape the next decade.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-BUS-003-dup-47', 'AI Impact', 'Hotel and Restaurant Management', 'HRM is safe at the level that matters most — the art of hospitality, the skill of cooking, the management of people and experiences. AI handles the booking and the inventory. You provide the service excellence that makes guests come back. Specialize in culinary arts, event management, or luxury hospitality for the best career trajectory.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-SCI-008', 'AI Impact', 'Environmental Science', 'Environmental Science is one of the safest and most future-proof degrees you can take. The climate crisis means the world desperately needs people who can measure, analyze, and solve environmental problems. AI gives you better tools for satellite monitoring and climate modeling — but the fieldwork, the community engagement, and the policy advocacy are still yours.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-sociology', 'AI Impact', 'Sociology', 'Sociology is transforming into one of the most relevant fields for understanding and critiquing the AI revolution. The sociologist who can analyze algorithmic bias, study how technology reshapes communities, and advise companies on social impact is in growing demand. Add data analysis skills and you bridge two worlds that need each other.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-AI-anthropology', 'AI Impact', 'Anthropology', 'Anthropology is a surprisingly robust career in the AI era. Tech companies now hire anthropologists to help them understand the people their products affect — and the Philippines'' extraordinary cultural diversity gives Filipino anthropology graduates a unique perspective. Add UX research skills and you can work in tech, development, or cultural heritage.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-development-communication', 'AI Impact', 'Development Communication', 'Development Communication is a niche career with a loyal employer base. UPLB''s DevCom program has alumni working in over 50 countries for the UN, USAID, and international NGOs. AI will automate the template-writing — but the community dialogue, the participatory communication planning, and the cultural translation work that makes development programs actually reach people — that is still yours.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-AI-customs-administration', 'AI Impact', 'Customs Administration', 'Customs Administration is honest — routine document processing is being automated fast. But the customs broker who handles complex tariff disputes, leads anti-smuggling investigations, and navigates the rapidly changing world of e-commerce customs regulations is still very much needed. Specialize in trade compliance, enforcement, or e-commerce customs to stay ahead.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-AI-office-administration', 'AI Impact', 'Office Administration', 'Office Administration is one of the most honest conversations about AI''s impact. Routine admin work — scheduling, filing, data entry, correspondence — is being automated fast. The path forward is clear: become the person who manages and optimizes the AI office tools, or specialize in executive support and complex project coordination where judgment matters. Do not plan to do routine admin work in 2030.', 'AI-Safe-Score 2/5 (At Risk)', 'AI_IMPACT'),
  ('aiimpact-AI-foreign-languages', 'AI Impact', 'Foreign Languages', 'Foreign Languages is transforming, not dying. AI handles routine translation — your value is in the high-stakes, culturally complex, legally precise work that machines still get wrong. Korean, Japanese, and Mandarin speakers have exceptional demand in the Philippine market right now. Pair your language skills with specialization in law, medicine, business, or diplomacy for the strongest career.', 'AI-Safe-Score 3/5 (Transforming)', 'AI_IMPACT'),
  ('aiimpact-AI-filipino-and-philippine-literature', 'AI Impact', 'Filipino and Philippine Literature', 'Filipino is actually one of the more AI-resistant language careers because AI still struggles with authentic Filipino. Your deep knowledge of Filipino culture, literature, and language nuance is something no model trained primarily on English can match. The local media, education, and AI training industries all need you — and your work preserves Filipino cultural identity.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-history', 'AI Impact', 'History', 'History is more relevant than ever in the age of AI misinformation. Your ability to analyze primary sources, question narratives, and provide accurate historical context is exactly what newsrooms, fact-checkers, and institutions need. Philippine history is also one of the most contested and important fields — your work helps the nation understand itself honestly.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-philosophy', 'AI Impact', 'Philosophy', 'Philosophy is secretly one of the best degrees you can take in the AI era. AI companies are literally hiring philosophers to work on ethics, safety, and the meaning of consciousness. Your training in critical thinking, logical argumentation, and value theory is exactly what the world needs to govern AI responsibly. Also — philosophy majors consistently score highest on the LSAT and GRE. Your options are wide open.', 'AI-Safe-Score 5/5 (Very Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-marine-science-marine-biology', 'AI Impact', 'Marine Science / Marine Biology', 'Marine Science is one of the most important and irreplaceable careers for the Philippines. We are the center of global marine biodiversity and one of the most ocean-dependent nations on Earth. AI gives you satellite data and automated species identification — but the reef surveys, the community engagement, and the conservation policy work that protects Philippine waters still need you in the water.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT'),
  ('aiimpact-AI-entrepreneurship', 'AI Impact', 'Entrepreneurship', 'Entrepreneurship is the degree most accelerated by AI. Every AI tool that lets you build faster, market smarter, and operate leaner makes being an entrepreneur more accessible. Your job is not to be replaced by AI — it is to use AI to build something the world needs. The Philippines needs Filipino founders who understand local problems deeply and can build solutions for them.', 'AI-Safe-Score 4/5 (Safe)', 'AI_IMPACT')
ON CONFLICT (id) DO UPDATE SET
  query_type   = EXCLUDED.query_type,
  course_name  = EXCLUDED.course_name,
  quick_answer = EXCLUDED.quick_answer,
  key_caveat   = EXCLUDED.key_caveat,
  point_to     = EXCLUDED.point_to;
